-- File 5 (step225): school media for Canada, United Kingdom and Australia from Wikipedia and Wikimedia Commons
-- (free licences), from the owner's fetch_school_media.py runs on 28 Nov 2026. Only fills empty fields; never overwrites.
-- Left out (wrong page matched): HEC Montréal (matched Polytechnique Montréal); Université du Québec en Outaouais (matched the Université du Québec network); University of Warwick (matched Warwick Arts Centre); Hartpury University (matched a rugby player); Leeds College of Music (matched University of Leeds); Robert Gordon University (matched its boat club); University of Edinburgh (matched Edinburgh Napier University); University of the Highlands and Islands (matched Inverness College); Australian Catholic University (matched Notre Dame Australia); The National Institute of Dramatic Art (matched AIM Dramatic Arts); TAFE Queensland (matched a closed TAFE institute); Bond University (matched a professor).
-- Trimmed: University of New England: logo was the University of New England in Maine, USA; The University of New South Wales: logo was UNSW Canberra; Falmouth University: photo was a shield; University of Buckingham: photo was a coat of arms; University of Central Lancashire: photo was the Cyprus campus; Northeastern University London: Wikipedia calls it public; it is listed as private. Swinburne and Southern Cross: the "photo" was the logo, used as the logo.
begin;
update public.schools s set
  logo_url = coalesce(nullif(s.logo_url,''), v.logo_url),
  logo_credit = case when coalesce(s.logo_url,'')='' then v.logo_credit else s.logo_credit end,
  image_url = coalesce(nullif(s.image_url,''), v.image_url),
  image_credit = case when coalesce(s.image_url,'')='' then v.image_credit else s.image_credit end,
  description = coalesce(nullif(s.description,''), v.description),
  description_credit = case when coalesce(s.description,'')='' then v.description_credit else s.description_credit end
from (values
('0d996d07-9006-427e-b299-4b5d115e9110'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Universit%C3%A4t_Montreal_Logo.svg/500px-Universit%C3%A4t_Montreal_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jean-Claude Lahaye (1923-1999), Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Universit%C3%A9_de_Montr%C3%A9al%2C_Pavillon_Roger-Gaudry.JPG/1280px-Universit%C3%A9_de_Montr%C3%A9al%2C_Pavillon_Roger-Gaudry.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Laurent Bélanger, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Université de Montréal is a French-language public research university in Montreal, Quebec, Canada. The university's main campus is located in the Côte-des-Neiges neighborhood of Côte-des-Neiges–Notre-Dame-de-Grâce on Mount Royal near the Outremont Summit, in the borough of Outremont. The institution comprises thirteen faculties, more than sixty departments and two affiliated schools: Polytechnique Montréal and HEC Montréal.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('6d889f9d-d0a9-401d-9036-d238c041207e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Logo_York_University.svg/500px-Logo_York_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: SVG erstellt mit Inkscape, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/YorkUComputerScienceAndEngineeringBuilding.jpg/1280px-YorkUComputerScienceAndEngineeringBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Raysonho @ Open Grid Scheduler / Grid Engine, Public domain, Wikimedia Commons$q$,$q$York University is a public research university based in Toronto, Ontario, Canada. It is Canada's third-largest university, with approximately 53,500 students, 7,000 faculty and staff, and over 375,000 alumni worldwide. It has 11 faculties, including the Lassonde School of Engineering, Schulich School of Business, Osgoode Hall Law School, Glendon College, and 32 research centres.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1263a1a6-98e8-42a9-8acd-2fd9acd61976'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Carleton_University_Logo.svg/500px-Carleton_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Carleton University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/CarletonUniversity2022.jpg/1280px-CarletonUniversity2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Harleyd613, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Carleton University is an English-language public research university in Ottawa, Ontario, Canada. Founded in 1942 as Carleton College, the institution originally operated as a private, non-denominational evening college to serve returning World War II veterans. Carleton was chartered as a university by the provincial government in 1952 through The Carleton University Act, which was then amended in 1957, giving the institution its current name.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e6e07660-48f0-420f-97ec-4dd4c8264457'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Universit%C3%A9_laval.jpg/500px-Universit%C3%A9_laval.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pisenr, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Pavillon_Louis-Jacques-Casault_-_Universit%C3%A9_-Laval_-_Quebec_City_-_October_2007.jpg/1280px-Pavillon_Louis-Jacques-Casault_-_Universit%C3%A9_-Laval_-_Quebec_City_-_October_2007.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Colin Rose from Montreal, Canada, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Université Laval is a public research university in Quebec City, Quebec, Canada. Université Laval traces its roots to the Séminaire de Québec, which was founded by François de Montmorency-Laval in 1663. Université Laval is the oldest institution of higher education in Canada, as well as the first North American institution to offer higher education in French.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e70bc46d-77be-4449-93e1-591f11e04eb0'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Acadia_University_1.jpg/1280px-Acadia_University_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ryan Stevens, CC BY 2.0, Wikimedia Commons$q$,$q$Acadia University is a public, predominantly undergraduate university located in Wolfville, Nova Scotia, Canada, with some graduate programs at the master's level and one at the doctoral level. The enabling legislation consists of the Acadia University Act and the Amended Acadia University Act 2000. The Wolfville Campus houses Acadia University Archives and the Acadia University Art Gallery.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('890bc234-8faf-4dcf-b8c5-da0dc787961a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/ECUAD-Logo_RGB.svg/500px-ECUAD-Logo_RGB.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Emily Carr University of Art and Design, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Emily_Carr_University_of_Art_and_Design%2C_exterior%2C_Vancouver%2C_BC_%28May_2025%29.jpg/1280px-Emily_Carr_University_of_Art_and_Design%2C_exterior%2C_Vancouver%2C_BC_%28May_2025%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: BriefEdits, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Emily Carr University of Art and Design is a public university of art and design located in Vancouver, British Columbia, Canada. Founded in 1925 as the Vancouver School of Decorative and Applied Arts, it is the oldest public post-secondary institution in British Columbia dedicated to professional education in the arts, media, and design. The university is named for Canadian artist and writer Emily Carr, who was known for her Modernist and Post-Impressionist artworks.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('94f34f2e-2f9d-4140-bf3e-f723ea13a7b0'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Mount_Royal_University_Logo.svg/500px-Mount_Royal_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mount Royal University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Mount-Royal-College-Szmurlo.jpg/1280px-Mount-Royal-College-Szmurlo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: No machine-readable author provided. Cszmurlo assumed (based on copyright claims, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Mount Royal University is a public university in Calgary, Alberta, Canada. Originally “Mount Royal College,” Mount Royal University was granted university status in 2009 by the provincial government. The university has an average class size of 30 students and currently offers 13 degrees and 37 majors, in addition to diplomas, post-bachelor certificates and a variety of credit-free programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4c3f0735-e2c3-4792-8c4f-042e744ce793'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Logo-uqar_2015.svg/500px-Logo-uqar_2015.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Rimouski_-_Entr%C3%A9e_principale.jpg/1280px-Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Rimouski_-_Entr%C3%A9e_principale.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AzertyFab, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Université du Québec à Rimouski is a public university located in Rimouski, Quebec, Canada, with a campus in Lévis. Established in 1969, UQAR offers academic training throughout eastern Quebec, including the Chaudière-Appalaches, Gaspésie–Îles-de-la-Madeleine, Haute-Côte-Nord, and Manicouagan areas. The university also has permanent offices in Gaspé and Rivière-du-Loup.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('03b25832-0531-4f09-ab3a-c82deba3bbde'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/UPEI_Wordmark.svg/500px-UPEI_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Prince Edward Island, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/UPEI_%282633716968%29.jpg/1280px-UPEI_%282633716968%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Martin Cathrae from Charlottetown, PE, Canada, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Prince Edward Island is a public university in Charlottetown, Prince Edward Island, Canada, and the only university in the province. Founded in 1969, the enabling legislation is the University Act, R.S.P.E.I 2000.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('972081bf-aef7-4383-b8b9-82365f3aedc3'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Concordia_univ_montreal_textlogo.png/500px-Concordia_univ_montreal_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/JMSB.jpg/1280px-JMSB.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: MTLskyline, Public domain, Wikimedia Commons$q$,$q$Concordia University is a public English-language research university located in Montreal, Quebec, Canada. Founded in 1974 with the merger of Loyola College and Sir George Williams University, Concordia is one of the three universities in Quebec where English is the primary language of instruction. As of the 2024–2025 academic year, there were 48,657 students enrolled in credit and non-credit courses at Concordia, making the university among the largest in Canada by enrollment.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Convocation_Hall_University_of_Alberta_Edmonton_Alberta_Canada_02.jpg/1280px-Convocation_Hall_University_of_Alberta_Edmonton_Alberta_Canada_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: WinterforceMedia WinterE229, Public domain, Wikimedia Commons$q$,$q$The University of Alberta is a public research university located in Edmonton, Alberta, Canada. It was founded in 1908 by Alexander Cameron Rutherford, the first premier of Alberta, and Henry Marshall Tory, the university's first president. It was enabled through the Post-secondary Learning Act.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('25decb60-25d8-47e8-8835-9c35ed464d65'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Algoma_University_wordmark.svg/500px-Algoma_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Algoma University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Algoma_University_2.JPG/1280px-Algoma_University_2.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Fungus Guy, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Algoma University, commonly shortened to Algoma U, is a Canadian public university in the province of Ontario, with campuses in Brampton, Sault Ste. Marie, and Timmins. Algoma U offers bachelor's degrees, master's degrees and graduate certificate programs in liberal arts, sciences and professional disciplines.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('66916c52-54ff-4d03-b765-f1289349f38a'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Mount_Saint_Vincent_University.jpg/1280px-Mount_Saint_Vincent_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: misterjerk2, Public domain, Wikimedia Commons$q$,$q$Mount Saint Vincent University, often referred to as the Mount, is a public, primarily undergraduate, university located in Halifax, Nova Scotia, Canada, and was established in 1873. Mount Saint Vincent offers undergraduate programs in arts, science, education, and professional studies. The Mount has 13 graduate degrees in Applied Human Nutrition, School Psychology, Child and Youth Study, Education, Family Studies and Gerontology, Public Relations and Women's Studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('43f9c4b4-d402-4679-9eaf-a8c36e64fc21'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/UofRegina_Logo.svg/500px-UofRegina_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Regina, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/University_of_Regina_Continuing_Development_Centre_-_Regina_%2829125895587%29.jpg/1280px-University_of_Regina_Continuing_Development_Centre_-_Regina_%2829125895587%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Haydn Blackey from Cardiff, Wales, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Regina is a public university located in Regina, Saskatchewan, Canada. Founded in 1911 as a private denominational high school of the Methodist Church of Canada, it began an association with the University of Saskatchewan as a junior college in 1925. It disaffiliated from its Methodist founders and fully ceded to the university in 1934; in 1961 it attained degree-granting status as the Regina Campus of the University of Saskatchewan.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3a2455d2-432a-44d5-a011-522c43a4c630'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/First_Nations_University_2021.jpg/1280px-First_Nations_University_2021.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: daryl_mitchell, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The First Nations University of Canada is a post-secondary institution and federated college of the University of Regina, based in the Canadian province of Saskatchewan. FNUniv operates three campuses within the province, in Prince Albert, Regina, and Saskatoon. The university offers academic programs in business, the humanities, social sciences, and sciences; including a number of programs focused around Indigenous practices.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('94adc91b-a5f8-4c63-b909-a4a918a7517d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Dalhousie_University_Wordmark_2014.svg/500px-Dalhousie_University_Wordmark_2014.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Henri_Hicks_Building%2C_Dalhousie_University.jpg/1280px-Henri_Hicks_Building%2C_Dalhousie_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: mricon, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Dalhousie University is a large public research university in Nova Scotia, Canada, with three campuses in Halifax, a fourth in Bible Hill, and two satellite medical school campuses, in Saint John, New Brunswick and in Cape Breton. Dalhousie offers over 200 degree programs in 13 undergraduate, graduate, and professional faculties. The university is a member of the U15, a group of research-intensive universities in Canada.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('058d3791-8d23-4e86-aeb3-c49071ef58c3'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Taylor-Institute-east-exterior-schulich.jpg/1280px-Taylor-Institute-east-exterior-schulich.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jgcab, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Calgary is a public research university located in Calgary, Alberta, Canada. The University of Calgary started in 1944 as the Calgary branch of the University of Alberta, founded in 1908, prior to being instituted into a separate, autonomous university in 1966. It is composed of 14 faculties and over 85 research institutes and centres.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('14adea28-4bd9-4410-8bcc-96ebce340d43'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Athabasca_University_Logo.svg/500px-Athabasca_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Athabasca University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/5/56/AU2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stephen Addison, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Athabasca University is a Canadian public university that primarily operates through online distance education. Founded in 1970, it is one of four comprehensive academic and research universities in Alberta, and was the first Canadian university to specialize in distance education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('977a83eb-de2f-4300-a44e-446400aa121d'::uuid,null,null,null,null,$q$Nipissing University is a public university located in North Bay, Ontario, Canada. Its scenic hilltop campus overlooks Lake Nipissing. The university has established a strong reputation in fields such as education, arts, science, business, and nursing, and is home to the prestigious Schulich School of Education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('6f88aa65-32f6-4164-aea2-fa65da5c34a7'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Winnipeg_univ_ca_textlogo.png/500px-Winnipeg_univ_ca_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/UofW.JPG/1280px-UofW.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: KrazyTea, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Winnipeg is a public research university in Winnipeg, Manitoba, Canada. It offers undergraduate programs in art, business, economics, education, science and applied health as well as graduate programs. UWinnipeg's founding colleges were Manitoba College and Wesley College, which merged to form United College in 1938.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cc9dd73d-3c07-42ec-a5db-904386ccebb7'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Fraser_valley_univ_logo.svg/500px-Fraser_valley_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,null,null,$q$The University of the Fraser Valley, formerly known as University College of the Fraser Valley and Fraser Valley College, is a public university with campuses in Abbotsford, Chilliwack, Mission and Hope, British Columbia, Canada. Founded in 1974 as Fraser Valley College, it was a response to the need for expanded vocational training in the communities of the Fraser Valley. In 1991, it became a university college, with degree-granting status.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('b6fb2eeb-1cca-4d51-83c5-265e609c32f5'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Mcgill_univ_ca_logo.png/500px-Mcgill_univ_ca_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: patent of arms for James McGill (1744–1813) granted by England's Garter-King-at-, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Arts_Building%2C_McGill_University%2C_Aug_31_2022.jpg/1280px-Arts_Building%2C_McGill_University%2C_Aug_31_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: D. Benjamin Miller, CC0, Wikimedia Commons$q$,$q$McGill University is an English-language public research university in Montreal, Quebec, Canada. Founded in 1821 by royal charter, the university bears the name of James McGill, a Scottish merchant, whose bequest in 1813 established the University of McGill College. In 1885, the name of the university was officially changed to McGill University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ec878c05-ccde-4f52-b45d-64d51c0b2550'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/UniversityOfManitobaAdministrationBuilding.jpg/1280px-UniversityOfManitobaAdministrationBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Manitoba is a public research university in Winnipeg, Manitoba, Canada. Founded in 1877, it is the first university in Western Canada. Both by total student enrolment and campus area, the University of Manitoba is the largest university in the province of Manitoba.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a1fa6a18-6be6-4ddc-a20f-9d42aa3ba4f7'::uuid,null,null,null,null,$q$Bishop's University is a small English-language liberal arts university in Lennoxville, a borough of Sherbrooke, Quebec, Canada. The founder of the institution was the Anglican Bishop of Quebec, George Mountain, who also served as the first principal of McGill University. It is one of three universities in the province of Quebec that teach primarily in English, with the others being McGill University and Concordia University, both in Montreal.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('db725d76-0aa4-4781-b3bf-c0ee4a1b510b'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/f/fc/Logo_INRS_-_Institut_national_de_la_recherche_scientifique.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Institut national de la recherche scientifique, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Edifice_quebec_INRS.jpg/1280px-Edifice_quebec_INRS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hélène Simard, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Institut national de la recherche scientifique is the research-oriented constituent university of the Université du Québec system that offers only graduate studies. INRS conducts research in four broad sectors: water, earth and the environment; energy, materials and telecommunications; human, animal and environmental health; and urbanization, culture and society. INRS has facilities in Quebec City, Montreal, Laval, and Varennes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('37fd285e-a0cf-4c17-9ea9-a401b84eea63'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/NSCAD_Logo.svg/500px-NSCAD_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: NSCAD University, Public domain, Wikimedia Commons$q$,null,null,$q$NSCAD University, also known as the Nova Scotia College of Art and Design, is a public art university in Halifax, Nova Scotia, Canada. The university is a co-educational institution that offers bachelor's and master's degrees. The university also provides continuing education services through its School of Extended Studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2cdbde41-b2bf-4824-baa6-325c17a2f374'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Thompson_River_University_3.jpg/1280px-Thompson_River_University_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kiyoteru Awaji, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Thompson Rivers University is a public research university in Kamloops, British Columbia, Canada. The university's name comes from the two rivers that converge in Kamloops, the North Thompson and South Thompson. TRU is one of six research universities in B.C. It is the province's only dual-sector research university—meaning it offers both academic and applied education—and offers a dual-sector education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('684f3c84-e5ea-4354-aa6f-88ff6a4fb907'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Univ_of_victoria_logo.png/500px-Univ_of_victoria_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/UVic_Clearihue_Building.jpg/1280px-UVic_Clearihue_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tloren5, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Victoria is a public research university located in the municipalities of Oak Bay and Saanich, British Columbia, Canada. It is a mid-to-large Canadian research university with strong environmental science, law, and Indigenous studies strengths, located in a coastal, nature-rich campus setting that emphasizes applied learning and sustainability. Established in 1903 as Victoria College, the institution was initially an affiliated college of McGill University until 1915.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('02422147-3142-4dd4-82e0-05ef9cd049bb'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/McMaster_University_campus.jpg/1280px-McMaster_University_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jokehoe, CC BY-SA 4.0, Wikimedia Commons$q$,$q$McMaster University is a public research university in Hamilton, Ontario, Canada. The main McMaster campus is on 152.4 hectares of land near the residential neighbourhoods of Ainslie Wood and Westdale, adjacent to the Royal Botanical Gardens. It operates six academic faculties: the DeGroote School of Business and the faculties of Engineering, Health Sciences, Humanities, Social Science, and Science.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('44b13810-abb8-45f8-a343-d738e56c03e4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Univ_ottawa_red_textlogo.png/500px-Univ_ottawa_red_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/UOttawa-Tabaret_Hall-2008-05-05.jpg/1280px-UOttawa-Tabaret_Hall-2008-05-05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: RobCA, Public domain, Wikimedia Commons$q$,$q$The University of Ottawa, often referred to as uOttawa, is a bilingual public research university in Ottawa, Ontario, the capital city of Canada. The main campus is located on 42.5 hectares directly to the northeast of Downtown Ottawa across the Rideau Canal in the Sandy Hill neighbourhood. The University of Ottawa was first established as the College of Bytown in 1848 by the first bishop of the Catholic Archdiocese of Ottawa, Joseph-Bruno Guigues.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('b5b26aa9-7174-4289-a4b3-02ce977d868d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Brandon_univ_textlogo.png/500px-Brandon_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/U_of_Brandon_-_Clark_Hall.jpg/1280px-U_of_Brandon_-_Clark_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Krazytea, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Brandon University is a university located in the city of Brandon, Manitoba, Canada, with an enrolment of approximately 3,375 full-time and part-time undergraduate and graduate students. The current location was founded on July 13, 1899, as Brandon College as a Baptist institution. It was chartered as a university by then President John E. Robbins on June 5, 1967.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bc5ef839-6d38-44be-be78-2f4e3ee46a60'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Kwantlen_Polytechnic_University_Logo.svg/500px-Kwantlen_Polytechnic_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kwantlen Polytechnic University, Public domain, Wikimedia Commons$q$,null,null,$q$Kwantlen Polytechnic University is a public undergraduate degree-granting polytechnic university in British Columbia, Canada, with campuses in Surrey, Richmond, Cloverdale, Whalley, and Langley. KPU is one of the largest institutions by enrolment in British Columbia garnering a total of 20,000 students and 1,400 faculty members across its five locations, encompassing the Metro Vancouver district. KPU provides undergraduate and vocational education including bachelor's degrees, associate degrees, diplomas, certificates, apprenticeships, and citations in more than 140 diverse programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a0208ac5-9d8e-4e3b-89f2-2b535aed71ca'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/OCAD_University_Logo.png/500px-OCAD_University_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bruce Mau Design, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/7/74/OCADNight1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: John Vetterli from Toronto, Canada, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Ontario College of Art and Design University, branded as OCAD University or OCAD U, is a public art university in Toronto, Ontario, Canada. Its main campus is located within Toronto's Grange Park and Entertainment District neighbourhoods. The university is co-educational and operates three academic faculties – the Faculty of Art, the Faculty of Arts and Science, and the Faculty of Design – which offer programs at the undergraduate and graduate levels, as well as certificate programs and continuing education courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('88bcb3aa-6b5c-442b-8f0e-d800ff050d32'::uuid,null,null,null,null,$q$Trent University is a public university in Peterborough, Ontario, with a satellite campus in Oshawa, which serves the Regional Municipality of Durham. Founded in 1964, the university is known for its Oxbridge college system and 11 on-campus nature reserves. The university's main Symons campus is located on the Otonabee River at the northeast corner of the City of Peterborough.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3eb529d0-4129-453f-8ec4-29ca24578bbd'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Universit%C3%A9_Sainte-Anne_Logo.svg/500px-Universit%C3%A9_Sainte-Anne_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Université Sainte-Anne, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/SteAnnes.jpg/1280px-SteAnnes.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Verne Equinox at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Université Sainte-Anne is a French-language university in Pointe-de-l'Église, Nova Scotia, Canada. It and the Université de Moncton in New Brunswick are the only French-language universities in the Maritime Provinces.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f22c4c6d-2d8f-44e9-806e-ae9acbe47ce7'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Windsor_univ_ca_textlogo.png/500px-Windsor_univ_ca_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/University_of_Windsor_Alumni_Hall.jpg/1280px-University_of_Windsor_Alumni_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Krylan22, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Windsor is a public research university in Windsor, Ontario, Canada. It is Canada's southernmost university. It has approximately 17,500 students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dc76ebd7-662f-444c-b60b-2b64ee8349d0'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/QueensU_Wordmark.svg/500px-QueensU_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Connormah, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Queen%27sDouglas.JPG/1280px-Queen%27sDouglas.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: No machine-readable author provided. GreenCommons assumed (based on copyright cl, Public domain, Wikimedia Commons$q$,$q$Queen's University at Kingston, commonly known as Queen's University or simply Queen's, is a public research university in Kingston, Ontario, Canada. Queen's holds more than 1,400 hectares of land throughout Ontario and owns Herstmonceux Castle in East Sussex, England. Queen's is organized into eight faculties and schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7cd9cb27-27e4-431b-ad9a-e03b10823242'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/CollegeBuilding-UofS.jpg/1280px-CollegeBuilding-UofS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: SriMesh, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Saskatchewan is a Canadian public research university, founded on March 19, 1907, and located on the east side of the South Saskatchewan River in Saskatoon, Saskatchewan, Canada. An "Act to establish and incorporate a University for the Province of Saskatchewan" was passed by the provincial legislature in 1907. It established the provincial university on March 19, 1907 "for the purpose of providing facilities for higher education in all its branches and enabling all persons without regard to race, creed or religion to take the fullest advantage".$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7bf7b280-9003-4b55-a54e-a544ed3b0fc3'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Brock_University_Logo_2022.svg/500px-Brock_University_Logo_2022.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Brock University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Brock_University_%287990168355%29.jpg/1280px-Brock_University_%287990168355%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Matt Clare from Burlington, Canada, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Brock University is a public research university in St. Catharines, Ontario, Canada. It is the only university in Canada in a UNESCO Biosphere Reserve, at the centre of Canada's Niagara Peninsula on the Niagara Escarpment.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a61a464c-6cb5-49e5-997b-1d7018f41641'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Lakehead_univ_textlogo.png/500px-Lakehead_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/0/07/Lakehead_University_Summer_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Office of Communications, Lakehead University, CC BY 2.5, Wikimedia Commons$q$,$q$Lakehead University is a public research university with campuses in Thunder Bay and Orillia, Ontario, Canada. Lakehead University, shortened to 'Lakehead U', is non-denominational and provincially supported. It has undergraduate programs, graduate programs, the Bora Laskin Faculty of Law, the only internationally accredited business school in northern Ontario, and is home to the western campus of the Northern Ontario School of Medicine.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f6203b95-163f-4a3c-814f-0dea05945d49'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/OntarioTech_primary_2019.svg/500px-OntarioTech_primary_2019.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ontario Tech University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/de/General_Motors_of_Canada_Automotive_Centre_of_Excellence.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Thehype2049, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Ontario Institute of Technology, branded as Ontario Tech University or Ontario Tech, is a public research university located in Oshawa, Ontario, Canada. The university's main campus is located on approximately 160 hectares of land in northern Oshawa, while its secondary satellite campus is situated in downtown Oshawa. The university is a co-educational institution that operates seven academic faculties.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('6e513a92-f6f4-4b57-8d66-36dd5be5be0f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Moncton_universite_logo.svg/500px-Moncton_universite_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/5/52/Universit%C3%A9_de_Moncton_Campus_de_Shippagan_1.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Claude Boucher, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Université de Moncton is a Canadian French-language university in New Brunswick. It includes campuses in Edmundston, Moncton, and Shippagan. The university was founded in 1963 following the recommendations of the royal commission on higher education in New Brunswick.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('673178d4-a435-458e-85a1-05f5f6b0080f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/TELUQ_rvb_500x174.png/500px-TELUQ_rvb_500x174.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dominique Fourcaudot (COMM-TÉLUQ), Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/T%C3%89LUQ_panorama.jpg/1280px-T%C3%89LUQ_panorama.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dominique Fourcaudot (COMM-TÉLUQ), CC BY-SA 4.0, Wikimedia Commons$q$,$q$Université TÉLUQ is a public French-language distance learning university, part of the Université du Québec system. Originally founded in 1972 as the Telé-université, Université du Québec commission to develop distance education courses, Université TÉLUQ is now a full university which offers programs in undergraduate and graduate studies. It is the only French-language university education institution in North America to offer all of its courses and programs at all three university cycles remotely and continuously.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3f7a27fb-5ed2-42f7-b5bc-33f873ea637d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Coat_of_Arms_of_Vancouver_Island_University.png/500px-Coat_of_Arms_of_Vancouver_Island_University.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: SheLikesHeraldry, CC BY 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Vancouver_Island_University_Faculty_of_Management.jpg/1280px-Vancouver_Island_University_Faculty_of_Management.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nle1229, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Vancouver Island University is a Canadian public research university serving Vancouver Island and coastal British Columbia. Malaspina College opened in 1969. The main campus is located in Nanaimo, with regional campuses in Duncan and Powell River.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ebe01186-bdc6-419d-a8d2-413ed97e168d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/SFU-block-logo.svg/500px-SFU-block-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Originally uploaded by Mwtoews, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Academic_quad_at_sfu.jpg/1280px-Academic_quad_at_sfu.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: kirsten, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Simon Fraser University is a public research university in British Columbia, Canada. It maintains three campuses in Greater Vancouver, respectively located in Burnaby, Surrey, and Downtown Vancouver. The 170-hectare main Burnaby campus on Burnaby Mountain, located 15 kilometres from downtown Vancouver, was established in 1965 and comprises more than 37,000 students and 200,000 alumni.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f6fa150f-e620-4559-b69e-5d50cae8aebb'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Facing_North.jpg/1280px-Facing_North.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: KTMAR, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Toronto is a public research university with three main campuses in Toronto and Mississauga, Ontario, Canada. It is the oldest institution of higher learning in Ontario, founded by royal charter in 1827 as King's College. Originally controlled by the Church of England, the university assumed its present name in 1850 upon becoming a secular institution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('325fa582-624c-4e07-8f75-0a3a94be267b'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/CapeBretonUniversityLogo.svg/500px-CapeBretonUniversityLogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cape Breton University The original uploader was MPen92 at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Shannon_School_of_Business.JPG/1280px-Shannon_School_of_Business.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: MPen92, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Cape Breton University is a public university located in Sydney, Nova Scotia, Canada. It is the only post-secondary degree-granting institution within the Cape Breton Regional Municipality and on Cape Breton Island. The university is enabled by the Cape Breton University Act passed by the Nova Scotia House of Assembly.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c0dae375-b222-4ebe-a687-3a290bdef5ad'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Laurentian_univ_textlogo.svg/500px-Laurentian_univ_textlogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Sudbury_fullsizeoutput_31fc_%2830570602508%29.jpg/1280px-Sudbury_fullsizeoutput_31fc_%2830570602508%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: JasonParis from Toronto, Canada, CC BY 2.0, Wikimedia Commons$q$,$q$Laurentian University, officially Laurentian University of Sudbury, is a mid-sized bilingual public university in Greater Sudbury, Ontario, Canada, incorporated on March 28, 1960. Laurentian offers a variety of undergraduate, graduate-level, and doctorate degrees. Laurentian is the largest bilingual provider of distance education in Canada.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('843e636b-f7a0-4029-9485-5b18e245469e'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/c/c9/Poly.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Polytechnique Montréal, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/%C3%89cole_Polytechnique_de_Montr%C3%A9al.jpg/1280px-%C3%89cole_Polytechnique_de_Montr%C3%A9al.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chicoutimi, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Polytechnique Montréal is a public research university affiliated with the Université de Montréal in Montreal, Quebec, Canada. The school offers graduate and postgraduate training, and is active in research. Following tradition, new Bachelors of Engineering graduating from Polytechnique Montréal receive an Iron Ring, during the Canadian Ritual of the Calling of an Engineer ceremony.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('11348a9e-21f4-4637-904a-7958fd445599'::uuid,null,null,null,null,$q$The Université de Saint-Boniface is a French-language public university located in the St. Boniface neighbourhood of Winnipeg, Manitoba, Canada. An affiliated institution of the University of Manitoba, the university offers general and specialized university degree programs as well as technical and professional training.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('df8e11c2-7f3a-43e2-b8ca-cf3e44a74c1b'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/University_of_Guelph_logo.svg/500px-University_of_Guelph_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Guelph, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Johnston_Green%2C_University_of_Guelph_-_Guelph%2C_ON_%282026%29-001.jpg/1280px-Johnston_Green%2C_University_of_Guelph_-_Guelph%2C_ON_%282026%29-001.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: JFVoll, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Guelph is a comprehensive public research university in Guelph, Ontario, Canada. It was established in 1964 after the amalgamation of Ontario Agricultural College, the MacDonald Institute, and the Ontario Veterinary College, and has since grown to an institution of over 30,000 students from more than 140 countries and employs 823 full-time faculty as of 2025. It offers 94 undergraduate degrees, 48 graduate programs, and 6 associate degrees in many different disciplines.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('663200da-f3f7-4c42-bf27-e2ace87fe988'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Laurier_univ_textlogo.png/500px-Laurier_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Schlegel_Centre_%28Laurier%27s_school_of_business_and_economics%29.JPG/1280px-Schlegel_Centre_%28Laurier%27s_school_of_business_and_economics%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: LeonV, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Wilfrid Laurier University is a Public university in Ontario, Canada, with campuses in Waterloo, Brantford and Milton. It is named in honour of Sir Wilfrid Laurier, the seventh prime minister of Canada. Laurier offers undergraduate and graduate programs in a variety of fields with over 17,000 full-time undergraduate students, over 1,000 full-time graduate students, and nearly 4,000 part-time students as of late 2019.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('09d436f1-10b1-44dc-aeb2-8864ad3f8cf8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/British_columbia_ca_univ_logo.svg/500px-British_columbia_ca_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Irving_K._Barber_Library.jpg/1280px-Irving_K._Barber_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: CjayD, CC BY 2.0, Wikimedia Commons$q$,$q$The University of British Columbia is a public research university with two main campuses near Vancouver and Kelowna, in British Columbia, Canada. With an annual research budget of $893 million, UBC funds 9,992 projects annually in various fields of study within the industrial sector, as well as governmental and non-governmental organizations. The Vancouver campus is situated on Point Grey campus lands, an unincorporated area bordering the University Endowment Lands in proximity to the City of Vancouver.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4648d072-a5b2-4f43-90a4-59b46c255646'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Uwaterloo_wordmark.svg/500px-Uwaterloo_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Waterloo, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/University_of_Waterloo_%28Waterloo_Campus%29_-_Waterloo%2C_Ontario.jpg/1280px-University_of_Waterloo_%28Waterloo_Campus%29_-_Waterloo%2C_Ontario.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: JFVoll, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Waterloo is a public research university located in Waterloo, Ontario, Canada. The main campus is on 404 hectares of land adjacent to uptown Waterloo and Waterloo Park. The university also operates three satellite campuses and four affiliated university colleges.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f9ea13d7-066f-4a6b-a2d8-dca321f7487d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/CapU_logo_horizontal_rgb.png/500px-CapU_logo_horizontal_rgb.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Capilano University, CC BY-SA 4.0, Wikimedia Commons$q$,null,null,$q$Capilano University is a teaching-focused public university based in North Vancouver, British Columbia, Canada, located on the slopes of the North Shore Mountains, with programming that also serves the Sea-to-Sky Corridor and the Sunshine Coast. The university is named after Chief Joe Capilano, leader of the Squamish people from 1895 to 1910. Capilano University's degree programs are approved by the Government of British Columbia's Ministry of Advanced Education, Skills and Training.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5928c28e-2d61-409e-9cd0-8a903a57432c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/MacEwanU-Logo.svg/500px-MacEwanU-Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: MacEwanMedia, Vectorization: Jeromi Mikhael, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/0/0e/MacEwan_University_Edmonton_%288726219457%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Kevin M Klerks from Inverhuron, Canada, CC BY 2.0, Wikimedia Commons$q$,$q$Grant MacEwan University, commonly known as MacEwan University, is a public university located in downtown Edmonton, Alberta, Canada. Originally established as a community college which was named in honour of Dr. Grant MacEwan, 9th Lieutenant Governor of Alberta in 1971, Grant MacEwan College officially transitioned into a university in 2009 under the Post-Secondary Learning Act.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a9e92987-4bc9-4cc7-a5e9-6d126d3e6b02'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Rmc_canada_textlogo.png/500px-Rmc_canada_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/RMC_Mackenzie_building.JPG/1280px-RMC_Mackenzie_building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: User S23678 on en.wikipedia, Public domain, Wikimedia Commons$q$,$q$The Royal Military College of Canada, abbreviated in English as RMC and in French as CMR, is a military academy and, since 1959, a degree-granting university of the Canadian Armed Forces. It was established in 1874 and conducted its first classes on June 1, 1876. Programs are offered at the undergraduate and graduate levels, both on campus as well as through the college's distance learning program via the Division of Continuing Studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('15fbcbf2-bf3f-4eea-9c88-c2e7e15bd68a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Universit%C3%A9_de_Sherbrooke_%28logo%29_%282%29.svg/500px-Universit%C3%A9_de_Sherbrooke_%28logo%29_%282%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Université de Sherbrooke, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Universit%C3%A9_de_Sherbrooke_-_Centre_multifonctionnel.jpg/1280px-Universit%C3%A9_de_Sherbrooke_-_Centre_multifonctionnel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: UncivilFire, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Université de Sherbrooke is a French-language public research university in Sherbrooke, Quebec, Canada, with a second campus in Longueuil, a suburb on the South Shore of Montreal. It is one of two universities in the Estrie region of Quebec, and the only French-language university for the region. As of 2022, the Université de Sherbrooke is home to 31,000 students, and an additional 3,000 older learners in continuing education in its "University of the Third Age".$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('524f5f1c-ee49-471e-ad25-8c4cff67313e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Lethbridge_univ_textlogo.png/500px-Lethbridge_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/d4/University_of_lethbridge_SU.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Keegan Mullin, Public domain, Wikimedia Commons$q$,$q$The University of Lethbridge is a public comprehensive and research university located in Lethbridge, Alberta, Canada, with a second campus in Calgary, Alberta, and until 2015 a third campus in Edmonton, Alberta. Founded in the liberal arts tradition, the university offers over 150 undergraduate degree programs in the Arts, Sciences, Management, Education, Health Sciences and Fine Arts. Further, the university has over 50 Masters and PhD programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('56e317bc-8ad5-4be1-a748-3614e352c65a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Yukon_University_logo.png/500px-Yukon_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Yukon University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Panorama_for_the_Yukon_College_Roof.jpg/1280px-Panorama_for_the_Yukon_College_Roof.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: grampymoose, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Yukon University is a public university in the Canadian territory of Yukon. The university's main campus is based in Whitehorse, although the institution also operates 12 campuses throughout the territory. The university confers bachelor's degrees, diplomas, certificates as well as trades and vocational training and adult basic education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d421e3c2-fb47-4406-b709-45b387aa3328'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/TMU_logo.svg/500px-TMU_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Toronto Metropolitan University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Toronto_Met_Student_Learning_Centre_at_night_2022.jpg/1280px-Toronto_Met_Student_Learning_Centre_at_night_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Canmenwalker, CC BY 4.0, Wikimedia Commons$q$,$q$Toronto Metropolitan University, formerly known as Ryerson University, is a public research university located in Toronto, Ontario, Canada. The university's core campus is situated within the Garden District in downtown Toronto, although it also operates facilities elsewhere in the city and a satellite campus in Brampton for its medical school. The university includes nine academic divisions: the Faculty of Arts, the Faculty of Community Services, the Faculty of Engineering and Architectural Science, the Faculty of Science, The Creative School, the Lincoln Alexander School of Law, the Ted Rogers School of Management, the School of Medicine, and the Yeates School of Graduate and Postdoctoral Studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3306b401-6559-4bf0-a40e-9c61f976c9bd'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Western_ontario_univ_textlogo.svg/500px-Western_ontario_univ_textlogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/University_College%2C_Western_University.jpg/1280px-University_College%2C_Western_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: R.schneider101, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Western Ontario is a public research university in London, Ontario, Canada. The main campus is located on 455 hectares of land, surrounded by residential neighbourhoods and the Thames River bisecting the campus's eastern portion. The university operates twelve academic faculties and schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2589b475-101d-4c24-a502-dcdfdf0c1810'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Ets_quebec_logo.png/500px-Ets_quebec_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Ecole_de_technologie_superieure_05.jpg/1280px-Ecole_de_technologie_superieure_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jeangagnon, CC BY-SA 3.0, Wikimedia Commons$q$,$q$École de technologie supérieure, founded in 1974, is a public research university in Montreal, Quebec, Canada and affiliated to the Université du Québec system. The school specializes in applied teaching and research in engineering as well as transferring advanced technologies to companies. In any given year, 25% of all engineers receiving a diploma from an engineering school or faculty in the province of Quebec graduate from the ÉTS. The school ranks second in Canada for the number of bachelor's degrees in engineering awarded at the undergraduate level.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e8930518-f9f3-4a63-a77d-230467e237f9'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Memorial_University_of_Newfoundland_Logo.svg/500px-Memorial_University_of_Newfoundland_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/MemorialUniversity.jpg/1280px-MemorialUniversity.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: User:Neelix, Public domain, Wikimedia Commons$q$,$q$Memorial University of Newfoundland, or MUN, is a public research university in the province of Newfoundland and Labrador, based in St. John's, with satellite campuses in Corner Brook, Happy Valley-Goose Bay, and Harlow, England. Memorial University offers certificate, diploma, undergraduate, graduate, and post-graduate programs, as well as online courses and degrees.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a01a23d1-90ee-49d2-b812-07a537408e97'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Royal_Roads_University.jpg/1280px-Royal_Roads_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Worldneedpeace, CC BY 3.0, Wikimedia Commons$q$,$q$Royal Roads University is a public university with its main campus in Colwood, British Columbia, Canada. The university is located at Hatley Park National Historic Site on Vancouver Island and is the successor to the Royal Roads Military College, which was originally a training base for naval officers and later Canadian Air Force and Army personnel. After the end of the Cold War, the college was decommissioned, however, it was reinstituted following negotiations between the Department of National Defence and the Government of British Columbia by which the Royal Roads University Act was passed, leading to the establishment of Royal Roads University in June 1995.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('94df807f-9cdd-44df-9b7e-8db7da679fb2'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/f/f8/CampusUQAC07_282.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: service des communications de l'UQAC, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Université du Québec à Chicoutimi, is a branch of the Université du Québec network founded in 1969 and based in the Chicoutimi borough of Saguenay, Quebec, Canada. UQAC has secondary study centres in La Malbaie, Saint-Félicien, Alma, and Sept-Îles. In 2017, 7500 students were registered and 209 professors worked for the university, making it the fourth largest of the ten Université du Québec branches, after Université du Québec à Montréal, Université du Québec à Trois-Rivières, and École de technologie supérieure.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('72cb9981-e655-4ffc-969c-0c0f43fa3d0e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/New_brunswick_univ_logo.svg/500px-New_brunswick_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/UNB_OldArtsBuilding.JPG/1280px-UNB_OldArtsBuilding.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Blazingluke at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of New Brunswick is a public research university with two primary campuses in Fredericton and Saint John, New Brunswick. It is the oldest English-language university in Canada. With Canada's oldest engineering programme, UNB is consistently ranked by the Times Higher Education amongst the top 300 engineering schools in the world, or top 3% of over 7,000 universities that offer engineering worldwide.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('8e598699-906c-4cde-8879-c27e86901921'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Mount_allison_univ_ca_logo.svg/500px-Mount_allison_univ_ca_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/1a/Purdy_Crawford_Centre_for_the_Arts.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Jmdc-chicago, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Mount Allison University, founded in 1839, is a public primarily undergraduate liberal arts university located in Sackville, New Brunswick, Canada. Mount Allison was the first university in the British Empire to award a baccalaureate to a woman. It was also the first university in Canada to grant a bachelor of arts to a woman.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4d3c356c-5dac-46ed-a0db-6e4259671937'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/St_mary_univ_halifax_textlogo.png/500px-St_mary_univ_halifax_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Saint_Marys_HFX.jpg/1280px-Saint_Marys_HFX.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Robert Alfers, Public domain, Wikimedia Commons$q$,$q$Saint Mary's University is a public university located in Halifax, Nova Scotia, Canada. The school is best known for having nationally leading programs in business and chemistry. The campus is situated in Halifax's South End and covers approximately 32 hectares.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c3742177-137c-4914-b402-649dfb30de01'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Montr%C3%A9al_Logo.svg/500px-Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Montr%C3%A9al_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Université du Québec à Montréal, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Pavillon_Judith-Jasmin_UQAM_2.jpg/1280px-Pavillon_Judith-Jasmin_UQAM_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Great11, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Université du Québec à Montréal is a French-language public research university based in Montreal, Quebec, Canada. It is the largest constituent element of the Université du Québec system. UQAM was founded on April 9, 1969, by the government of Quebec, through the merger of the École des beaux-arts de Montréal, a fine arts school; the Collège Sainte-Marie, a classical college; and a number of smaller schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('15494535-de6a-44b3-8dcf-0b37ef2d8ce4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/UNBC_Logo.svg/500px-UNBC_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Northern British Columbia, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/UNBC.jpg/1280px-UNBC.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Thegrammarguy, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Northern British Columbia is a university serving the northern region of the Canadian province of British Columbia. The main campus is located in Prince George, with additional campuses located in Prince Rupert, Terrace, Quesnel, and Fort St. John.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('44951b5b-94ed-4c99-bd13-9841ccad64f6'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/37/University_Canada_West_%28UCW%29_-_Vancouver.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University Canada West, CC BY-SA 4.0, Wikimedia Commons$q$,$q$University Canada West is a private, for-profit university in British Columbia, Canada. It was founded in 2005 by David F. Strong, the former president of the University of Victoria. UCW was purchased in 2008 by the Eminata Group and in 2014 sold to Global University Systems, its present owners.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('664b56f4-528e-44d3-ab9e-16f937048852'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Trinity_west_univ_logo.png/500px-Trinity_west_univ_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Aerial_-_April_%2713-52_copy.jpg/1280px-Aerial_-_April_%2713-52_copy.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Charlesdclee, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Trinity Western University is a private Christian liberal arts college and research university with campuses in Langley and Richmond, British Columbia, Canada. TWU is a research institution offering undergraduate and graduate degrees in the humanities and sciences as well as in several professional schools. The school is a member of Universities Canada and the Council for Christian Colleges and Universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e4ba81b1-0b9f-445b-9fdc-28ce7669c33a'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Redeemer_University_-_Ancaster%2C_ON.jpg/1280px-Redeemer_University_-_Ancaster%2C_ON.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: JFVoll, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Redeemer University is a private Christian liberal arts and science university located in Hamilton, Ontario, Canada, in the community of Ancaster. Founded in 1982, Redeemer stands in the Reformed Tradition and offers Bachelor of Arts, Bachelor of Education, Bachelor of Business Administration, Bachelor of Science, Bachelor of Health Science, Bachelor of Kinesiology, and Bachelor of Communications and Media Studies degrees. Beginning in fall 2026, the university will offer its first master's degree, a Master of Education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ecd0b0b2-258f-4f74-ac35-c75d89cf2107'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/37/SimonaMaaskantLibrary.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Tracklan2, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The King's University in Edmonton, Alberta, Canada, is a Canadian Christian university offering bachelor's degrees in the arts, humanities, music, social sciences, natural sciences, business, and education. King's is one of 26 publicly funded post-secondary institutions in Alberta. The university serves more than 900 students from across Canada and abroad, representing more than 16 nations.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e0141db8-9f71-4df4-bc29-e3c1d6a0fe34'::uuid,null,null,null,null,$q$Crandall University is a Christian liberal arts university located in Moncton, New Brunswick, Canada. It is owned and operated by the Canadian Baptists of Atlantic Canada, which appoints a majority of its board of governors.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('8bb84e1d-9042-4a75-8fd2-270c9bbbfef6'::uuid,null,null,null,null,$q$Yorkville University is a private for-profit university established in 2003 with locations in Ontario, British Columbia, and New Brunswick, Canada. The university accepted its first students in the fall of 2004 for the programs offered out of Fredericton, New Brunswick, which was at the time the only establishment under Yorkville University. The university has since launched a brick-and-mortar campus in Vancouver, British Columbia, and acquired two brick-and-mortar campuses in Toronto, Ontario.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e219386a-3eb7-4bd5-bf1d-fcb26133b38d'::uuid,null,null,null,null,$q$Ambrose University is a publicly funded independent Christian liberal arts university located in Calgary, Alberta, Canada.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c9994d5b-7e27-4943-919a-3259596ba7da'::uuid,null,null,null,null,$q$Canadian Mennonite University is a private Mennonite university located in Winnipeg, Manitoba, Canada. It is affiliated with the Mennonite Church Canada and the Mennonite Brethren Church of Manitoba. The university was chartered in 1999 with a Shaftesbury campus in southwest Winnipeg, as well as Menno Simons College and a campus at the University of Winnipeg.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9ceb568a-5e21-4809-a8a9-8aebfefb690c'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/1/17/Open_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The Open University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Robert_Hook_building_at_Open_University_Campus_in_Milton_Keynes%2C_spring_2013_%282%29.JPG/1280px-Robert_Hook_building_at_Open_University_Campus_in_Milton_Keynes%2C_spring_2013_%282%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chmee2, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Open University is a public research university and the largest university in the United Kingdom by number of students. The majority of the OU's undergraduate students are based in the United Kingdom and principally study off-campus; many of its courses can also be studied anywhere in the world. There are also a number of full-time postgraduate research students based on the 45 ha university campus at Walton Hall in Milton Keynes, Buckinghamshire, where they use the staff facilities for research, as well as more than 1,000 members of academic and research staff and over 2,500 administrative, operational and support staff.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a6eaa4c7-f554-438c-bdff-44599747e72f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/University_of_Oxford.svg/500px-University_of_Oxford.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Oxford, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/1_oxford_aerial_panorama_2016.jpg/1280px-1_oxford_aerial_panorama_2016.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chensiyuan, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Oxford is a collegiate research university in Oxford, England. There is evidence of teaching as early as 1096, making it the oldest university in the English-speaking world and the world's second-oldest university in continuous operation. It grew rapidly from 1167, when Henry II prohibited English students from attending the University of Paris.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9b3f2d36-2f11-45cc-bc7f-4a91495200ef'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Birkbeck%2C_University_of_London.png/500px-Birkbeck%2C_University_of_London.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Aduclehomo, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/Birkbeck_College%2C_University_of_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Matt From London, CC BY 2.0, Wikimedia Commons$q$,$q$Birkbeck College, University of London is a public research university located in the Bloomsbury district of London, England. It is a member institution of the University of London. Established in 1823 as the London Mechanics' Institute by its founder Joseph Clinton Robertson and its supporters George Birkbeck, Jeremy Bentham, J. C. Hobhouse and Henry Brougham, Birkbeck is one of the few universities to specialise in evening higher education in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('019e9a45-1c64-47f3-b9cb-3ecd680c0b6e'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Bar_42_UCE_Birmingham.JPG/1280px-Bar_42_UCE_Birmingham.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: David Waterson (DWaterson), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Birmingham City University is a public university in Birmingham, England. Initially established as the Birmingham College of Art with roots dating back to 1843, it was designated as a polytechnic in 1971 and gained university status in 1992. The university has two main campuses serving four faculties, and offers courses in art and design, business, the built environment, computing, education, engineering, English, healthcare, law, the performing arts, social sciences, and technology.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('794586fb-1f9e-4bb4-893b-2d037a30aff6'::uuid,null,null,null,null,$q$Harper Adams University is a land-based public university in Edgmond, Shropshire, United Kingdom. Established in 1901 as Harper Adams College, Harper Adams University gained university status in 2012 and is a member of the Land Based Colleges Aspiring to Excellence.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cdbae795-0b76-4732-94a2-8a39b4700cf6'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Marjon_campus_main_entrance.jpg/1280px-Marjon_campus_main_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chris McKenna, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Plymouth Marjon University, commonly referred to as Marjon, is the trading name of the University of St Mark and St John, a university based primarily on a single campus on the northern edge of Plymouth, Devon, United Kingdom. Formerly named University College Plymouth St Mark & St John, the institution was awarded full university status in 2013. The Vice-Chancellor of the university since 2023 is Professor Claire Taylor.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f2284fd4-027c-4164-b37e-d2235072aefe'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Staffordshire_University_Logo.svg/500px-Staffordshire_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Staffordshire University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/f/fe/Staffordshire_University%2C_College_Road%2C_Stoke_-_geograph.org.uk_-_332924.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Steven Birks, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Staffordshire is a public research university in Staffordshire, England. It has its main campus in Stoke-on-Trent and two other campuses in Stafford, and London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('02b6ec3a-f95a-404f-bc20-8d9a4c93c97c'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/a/a4/University_of_Stirling_-_Dormitories.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Roger Wollstadt from Sarasota, Florida, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Stirling is a public university in Stirling, Scotland, founded by a royal charter in 1967. It is located in the Central Belt of Scotland, built within the walled Airthrey Castle estate. The university campus is approximately 360 acres in size, incorporating the Stirling University Innovation Park and the Dementia Centre.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c1af869a-6bf8-4d05-94dc-96855cd531e8'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/2/29/University_of_Strathclyde_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Flickr User StrathclydeGuy, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Strathclyde is a public research university located in Glasgow, Scotland. Founded in 1796 as the Andersonian Institute, it is Glasgow's second-oldest university, having received its royal charter in 1964 as the first technological university in the United Kingdom. Taking its name from the historic Kingdom of Strathclyde, its combined enrolment of 25,000 undergraduate and graduate students ranks it Scotland's third-largest university, drawn with its staff from over 100 countries.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dedea4a1-14e5-4b64-92e2-d0a5ecf73dcf'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/f/f5/University_Campus_Suffolk_-_geograph.org.uk_-_2839736.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: N Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Suffolk is a public university situated in Suffolk and Norfolk, England. The university was established in 2007 as University Campus Suffolk, founded as a collaboration between the University of East Anglia and the University of Essex. The university's current name was adopted after it was granted independence in 2016 by the Privy Council and was awarded university status.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('940a1726-859c-4338-886b-7a98779f0faa'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/University_of_Gloucestershire_logo.svg/500px-University_of_Gloucestershire_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,null,null,$q$The University of Gloucestershire is a public university based in Gloucestershire, England. It is located over four campuses; two in Cheltenham and two in Gloucester. The university is the successor of a large number of merged, name-changed and reformed institutions of further and higher education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('890c87b2-1836-466d-9c21-682267722e24'::uuid,null,null,null,null,$q$The University of Sunderland is a public research university located in Sunderland in the North East of England. Its predecessor, Sunderland Technical College, was established as a municipal training college in 1901. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5d9e6649-6ab9-4096-95f0-591649f2c6fc'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Arts_University_Bournemouth_campus%2C_library_%26_MoDiP.jpg/1280px-Arts_University_Bournemouth_campus%2C_library_%26_MoDiP.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: proficient-moose, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Arts University Bournemouth is a public university in Poole, England, specialising in art, architecture, film, performance, and design. Established in 1880, the university has been ranked Silver and Gold by the Teaching Excellence Framework in 2017, and was rated Outstanding by Ofsted, having retained this highest ranking since 2018. The Bournemouth Film School, a division of the university, was established in 1963 and is a full member of CILECT. AUB alumni include BAFTA and Academy Award winning filmmakers, and a Turner Prize recipient.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1fdba734-8ef7-4cae-997b-99b398b3f30f'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Senate_House_UoL.jpg/1280px-Senate_House_UoL.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: An Siarach at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of London is a federal public research university in London, England, United Kingdom. The university was established by royal charter in 1836 as a degree-awarding examination board for students holding certificates from University College London, King's College London, and "other such institutions, corporate or unincorporated, as shall be established for the purpose of Education, whether within the Metropolis or elsewhere within our United Kingdom". It is one of three institutions to have claimed the title of the third-oldest university in England.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('48ea74c8-a747-4f8e-a065-25fdfb2bc532'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/University_of_Cambridge_logo.png/500px-University_of_Cambridge_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dm980cam, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/St_John%27s_College_Second_Court%2C_Cambridge%2C_UK_-_Diliff.jpg/1280px-St_John%27s_College_Second_Court%2C_Cambridge%2C_UK_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Cambridge is a collegiate public research university in Cambridge, England. Founded in 1209, the University of Cambridge is the second-oldest university in the English-speaking world and the world's third-oldest university in continuous operation. The university's founding followed the arrival of scholars who left the University of Oxford for Cambridge after a dispute with local townspeople.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('115460e6-23f1-45f9-bbaa-10b742effe13'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/At_London_2024_117.jpg/1280px-At_London_2024_117.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Photograph by Mike Peel (www.mikepeel.net)., CC BY-SA 4.0, Wikimedia Commons$q$,$q$Regent's University London is a private university in London, in the United Kingdom. It is part of the multi-national education group Galileo Global Education. The university was established in 1984 as Regent's College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d3beff99-e55d-4903-8e42-1c59188ec973'::uuid,null,null,null,null,$q$The University of Buckingham is a non-profit private university in Buckingham, England, and the oldest of the country's six private universities. It was founded as the University College at Buckingham in 1973 and admitted its first students in 1976. It was granted university status by royal charter in 1983.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0135f5e0-3b52-450b-b0c8-4442ede116d3'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Northeastern_University_London_Wordmark.svg/500px-Northeastern_University_London_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Northeastern University, Public domain, Wikimedia Commons$q$,null,null,null,null),
('86bc16c1-621e-48c9-bb89-2500fce7b044'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/a/a7/Richmond_American_University_in_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: HTUK at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Richmond American University London is a private university in London, United Kingdom. Richmond was founded in 1972, by British educator Cyril Taylor. The university awards US degrees from the American state of Delaware, where Richmond is accredited by the Middle States Commission on Higher Education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0fd54c25-65d6-480e-aad6-e784a5a6b6f4'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/University_of_Law%2C_Bristol_campus.jpg/1280px-University_of_Law%2C_Bristol_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Assimifne, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Law is a publicly-funded, for-profit university in the United Kingdom, providing undergraduate and postgraduate degrees in law, business, psychology, criminology, policing and computer science. It also provides postgraduate courses in education, and specialist legal training and continuing professional development courses for British barristers, solicitors and trainees; it is the United Kingdom's largest law school. It traces its origins to 1876.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f99739d9-e73d-4eba-8466-e197efb2b416'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/35/Abertaylib.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Tam155 at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Abertay University is a public university in the city of Dundee, Scotland. In 1872, Sir David Baxter, 1st Baronet of Kilmaron, left a bequest for the establishment of a mechanics' institute in Dundee and the Dundee Institute of Technology was formed in 1888. As early as 1902 it was recognised by the Scottish Education Department as an educational hub, and was one of the first to be designated a central institution, akin to an "industrial university".$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e6e62e9e-2254-40f0-816f-333727cdf6c5'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Anglia_Ruskin_Cambridge_Main%2C_28_Sep%2C_2012.jpg/1280px-Anglia_Ruskin_Cambridge_Main%2C_28_Sep%2C_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mohammed Tawsif Salam, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Anglia Ruskin University is a public research university in the region of East Anglia, United Kingdom. Its origins date back to the Cambridge School of Art, founded in 1858 by William John Beamont, a Fellow of Trinity College at the University of Cambridge. The institution became a university in 1992 and was renamed after John Ruskin, the Oxford University professor and author, in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dd89831a-8897-4848-b322-ba8ac5c41429'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Arts_University_Plymouth.jpg/1280px-Arts_University_Plymouth.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Onlytruejames, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Arts University Plymouth is a public university located in Plymouth in South West England. The former Plymouth College of Art was officially granted university status in 2022. In April 2019 the specialist college was awarded taught degree awarding powers by the Quality Assurance Agency for Higher Education, granting the institution the authority to award and accredit its own BA degrees and Masters awards.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('10c2ca8c-162f-4a4a-8ebf-68beee83feca'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/b/b5/Aston_University_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Copyrighted official logo for Aston University, UK., Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Aston_Uni_Lakeside_01.JPG/1280px-Aston_Uni_Lakeside_01.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, Public domain, Wikimedia Commons$q$,$q$Aston University is a public university situated in the city centre of Birmingham, England. Aston began as the Birmingham Municipal Technical School in 1895, evolving into the UK's first college of advanced technology in 1956. Aston University received its royal charter from Queen Elizabeth II on 22 April 1966.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e0928483-71a7-4a37-bb05-da8b2c3b3e72'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Bangor_University_%2850555605717%29.jpg/1280px-Bangor_University_%2850555605717%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Andrew Woodvine from Bangor, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Bangor University is a public research university in Bangor, Gwynedd, Wales. It was established in 1884 as the University College of North Wales, and received a Royal Charter in 1885. In 1893 it became one of the founding institutions of the federal University of Wales.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f50d2f6b-5ee4-482b-9c0d-1f1f9ea60cb1'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Bath_Spa_University_logo.svg/500px-Bath_Spa_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bath Spa University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/0/03/Bath-spa-university-feature-image-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Bath Spa University, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Bath Spa University is a public university in Bath, England, with its main campus at Newton Park, about 3+1⁄2 miles west of the centre of the city. The university has other campuses in the city of Bath and London, as well as a site at Corsham Court in Wiltshire. The institution gained full university status in August 2005, having been previously known as Bath College of Higher Education, and later Bath Spa University College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('18e6fd83-1046-40af-8359-010b114e89bc'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Bournemouth_Uni_entrance.jpg/1280px-Bournemouth_Uni_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tom Morris, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Bournemouth University is a public university in Bournemouth, England, with its main campus situated in neighbouring Poole. The university was founded in 1992; however, the origins of its predecessor date back to the early 1900s. The university currently has over 17,000 students, including over 3,000 international students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('929be3d6-a532-428d-8ae9-73f6e825fc63'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/4/42/New_Logo_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: BenSalem1, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/6c/The_Wilfred_Brown_Building_at_Brunel_University_-_geograph.org.uk_-_1518813.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Basher Eyre, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Brunel University of London is a public research university located in the Uxbridge area of London, England. It is named after Isambard Kingdom Brunel, a Victorian engineer and pioneer of the Industrial Revolution. It became a university in June 1966, when Brunel College of Advanced Technology was awarded a royal charter and became Brunel University; it is sometimes considered a plate glass university.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ac3aaad3-4944-4672-91c7-43e843c63756'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Buckinghamshire_New_University.jpg/500px-Buckinghamshire_New_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Buckinghamshire New University, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Gateway_building%2C_Buckinghamshire_New_University%2C_High_Wycombe%2C_Buckinghamshire_-_July_2026_-_01.jpg/1280px-Gateway_building%2C_Buckinghamshire_New_University%2C_High_Wycombe%2C_Buckinghamshire_-_July_2026_-_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mertbiol, CC0, Wikimedia Commons$q$,$q$Buckinghamshire New University is a public university in Buckinghamshire, England, with campuses in High Wycombe and Uxbridge. Originally established as the School of Science and Art in 1891, it has grown into a university offering more than 200 courses across areas including health, nursing, business, aviation, creative industries and technology. This provision is delivered through three academic colleges: the College of Leadership and Innovation, the College of Health and Society, and the College of Creative Arts, Technology and Engineering.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2f8ad330-6dc8-4e7e-a167-c4a0419a4df2'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/4/45/Canterbury_Christ_Church_University_-_geograph.org.uk_-_984484.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Nigel Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Canterbury Christ Church University is a public research university located in Canterbury, Kent, England. Founded as a Church of England college for teacher training in 1962, it was granted university status in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('08e682ed-8f53-48d5-98af-c0d0bfc7a7ca'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/UWIC_Llandaff_Cardiff.JPG/1280px-UWIC_Llandaff_Cardiff.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Welshleprechaun, Public domain, Wikimedia Commons$q$,$q$Cardiff Metropolitan University is a public university located in Cardiff, Wales. It was formerly known as the University of Wales Institute, Cardiff which was established in 1996. The university offers degree courses in a variety of disciplines.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('92dcb85b-bbe8-4622-8f04-401d314c0aa8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Cardiff_University_%28logo%29.svg/500px-Cardiff_University_%28logo%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cardiff University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/44/Cardiff_University_main_building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stan Zurek, Public domain, Wikimedia Commons$q$,$q$Cardiff University is a public research university in Cardiff, Wales. It was established in 1883 as the University College of South Wales and Monmouthshire and became a founding college of the University of Wales in 1893. It was renamed University College, Cardiff in 1972 and merged with the University of Wales Institute of Science and Technology in 1988 to become University of Wales College, Cardiff and then University of Wales, Cardiff in 1996.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f38630ab-9064-4e5b-afe7-3ef9c993db2c'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/31/CollegeBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Normal4norfolk at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$City St George's, University of London is a public research university in London, England, and a member institution of the University of London. Founded in 1894 as the Northampton Institute, it officially became a university when the City University was created by royal charter in 1966. The Inns of Court School of Law, which merged with City in 2001, was established in 1852.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('51d90971-32d3-45e8-b3ce-ec0d46255835'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/CU_Coventry.png/500px-CU_Coventry.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ciaran McCormick, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Coventry_University.jpeg/1280px-Coventry_University.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY 2.5, Wikimedia Commons$q$,$q$Coventry University is a public research university in Coventry, England. The origins of Coventry University can be linked to the Coventry School of Design in 1843. It was known as Lanchester Polytechnic from 1970 until 1987, and then as Coventry Polytechnic until it gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cf14321d-6c4b-478e-9b43-f3f2d33c5a97'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Hawthorn_Building2.jpg/1280px-Hawthorn_Building2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jack O'Sullivan, CC BY 2.0, Wikimedia Commons$q$,$q$De Montfort University Leicester is a public university in Leicester, England. The university traces its origins to the Leicester School of Art, founded in 1870, and gained university status in 1992 under the Further and Higher Education Act. It is named after Simon de Montfort, a 13th-century Earl of Leicester who played a major role in England's constitutional development.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fe1c96c5-b12f-493c-b433-9bf9b3b84836'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/5/52/Edge_Hill_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edge Hill University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b4/Faculty_of_Health_and_Social_Care.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edge Hill University, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Edge Hill University is a campus-based public university in Ormskirk, Lancashire, England. The university, which originally opened in 1885 as Edge Hill College, was the first non-denominational teacher training college for women in England, before admitting its first male students in 1959. In 2005, Edge Hill was granted Taught Degree Awarding Powers by the Privy Council and became Edge Hill University on 18 May 2006.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('50603186-fe0f-4bc8-8d93-38cfc7d0eb54'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/b/b7/Craiglockhart.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edinburgh Napier University, Public domain, Wikimedia Commons$q$,$q$Edinburgh Napier University is a public university in Edinburgh, Scotland. Napier Technical College, the predecessor of the university, was founded in 1964, taking its name from 16th-century Scottish mathematician and philosopher John Napier. The technical college was inaugurated as a university in 1992 by Lord Douglas-Hamilton, becoming Napier University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('99ebb4ec-bc17-45b4-8efa-a02310f51efa'::uuid,null,null,null,null,$q$Falmouth University is a specialist public university for the creative industries based in Falmouth and Penryn in Cornwall, UK. Founded as Falmouth School of Art in 1902, it was later known as Falmouth College of Art and Design and then Falmouth College of Arts until 2012, when the university college was officially granted full university status by the Privy Council. The university is located across two campuses, in the towns of Penryn and Falmouth. Penryn Campus, near the town of Penryn, is the larger of its two campuses, which it operates in partnership with the University of Exeter.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1f4b219b-d8da-4f54-94b2-e972ad9d9d41'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/2/2e/GCUlogo_251px.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Glasgow Caledonian University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/13/GCU_Campus_View.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Knwwsss, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Glasgow Caledonian University, is a public university in Glasgow, Scotland. It was formed in 1993 by the merger of The Queen's College, Glasgow and Glasgow Polytechnic, founded in 1971). It is located in the Cowcaddens district, just to the immediate north of the city centre, and is one of three universities in Glasgow alongside the University of Glasgow and the University of Strathclyde.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('137988d7-8611-4bf6-9a45-ca409ce67ac8'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/4/4e/Goldsmithsnew.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: GUL, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/37/Goldsmiths_Main_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Alex Blandford, CC BY 2.0, Wikimedia Commons$q$,$q$Goldsmiths, University of London, formerly Goldsmiths' College, University of London, is a constituent research university of the University of London. It was originally founded in 1891 as The Goldsmiths' Technical and Recreative Institute by the Worshipful Company of Goldsmiths in New Cross, London. It was renamed Goldsmiths' College after being acquired by the University of London in 1904, and specialises in the arts, design, computing, humanities and social sciences.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('6ea0cd23-f96f-47fe-b160-c2a1b73d0263'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/5/5a/Heriot_Watt_University_Scottish_Borders_Campus_-_geograph.org.uk_-_210840.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Walter Baxter, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Heriot-Watt University is a public research university based in Edinburgh, Scotland. It was established in 1821 as the Edinburgh School of Arts, the world's first mechanics' institute, and was subsequently granted university status by royal charter in 1966. It is the eighth-oldest higher education institution in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9f7b0689-8405-4bf6-85f3-17fb108eef91'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Imperial_College_London_new_logo.png/500px-Imperial_College_London_new_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Imperial College London, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Imperial_College_London_down_Exhibition_Road.jpg/1280px-Imperial_College_London_down_Exhibition_Road.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Shadowssettle, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Imperial College of Science, Technology and Medicine, known by its trade names Imperial College London and Imperial, is a public research university in London, England. Its history began with Prince Albert, husband of Queen Victoria, who envisioned South Kensington as a cultural district with museums, colleges, and the Royal Albert Hall. In 1907, two colleges – the Royal College of Science and the Royal School of Mines – merged to form Imperial College London, with City and Guilds College joining in 1910.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a4a3431f-ef33-4eac-8caf-f85c816f28b7'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Kcl-logo.svg/500px-Kcl-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: reviczky, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/7/70/Strand102.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Flaming Ferrari (talk), Public domain, Wikimedia Commons$q$,$q$King's College London is a public research university in London, England. King's was established by royal charter in 1829 under the patronage of King George IV and the Duke of Wellington. In 1836, King's became one of the two founding colleges of the University of London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3825c081-38c9-4e9f-b594-dd4c06621249'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Kingston_University_logo.svg/500px-Kingston_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: The original uploader was Sakurambo at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/8/8e/Knights_Park_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Public domain, Wikimedia Commons$q$,$q$Kingston University London is a public research university located within the Royal Borough of Kingston upon Thames, in South West London, England. Its roots go back to the Kingston Technical Institute, founded in 1899. It received university status in 1992, before which the institution was known as Kingston Polytechnic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('671b712b-63d7-45f0-8301-4b6057370923'::uuid,null,null,null,null,$q$The University of Lancashire is a public university based in the city of Preston, Lancashire, England. It has its roots in The Institution For The Diffusion Of Useful Knowledge, founded in 1828. Previously known as the University of Central Lancashire, Harris Art College, Preston Polytechnic and Lancashire Polytechnic, in 1992 it was granted university status by the Privy Council.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7ea3eb59-2d9e-4ddf-bc31-8417817f36bf'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Lancaster_University_Courtyard.JPG/1280px-Lancaster_University_Courtyard.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Christoph Michels, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Lancaster University is a collegiate public research university in Lancaster, Lancashire, England. The university was established in 1964 by royal charter, as one of several new universities created in the 1960s. The university was initially based in St Leonard's Gate in the city centre, before starting a move in 1967 to a purpose-built campus located on 300 acres at Bailrigg, 4 km to the south of the city.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c51b7314-d316-4d22-ad45-578aa26d0447'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/7/7b/Leeds_College_of_Art_and_Design_-_geograph.org.uk_-_385408.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Betty Longbottom, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Leeds Arts University is a specialist arts further and higher education institution, based in the city of Leeds, West Yorkshire, England, with a main campus opposite the University of Leeds.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('36de4a32-7308-4197-bab0-5a7d54d99e9d'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/LBU_entrance_cropped_2015_01.jpg/1280px-LBU_entrance_cropped_2015_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, cropped by Blackcat, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Leeds Beckett University, formerly known as Leeds Metropolitan University and before that as Leeds Polytechnic, is a public university in Leeds, West Yorkshire, England. It has campuses in the city centre and Headingley. The university's origins can be traced to 1824, with the foundation of the Leeds Mechanics Institute.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c3be4dce-2e9c-4f88-b6d9-bddea073243d'::uuid,null,null,null,null,$q$Birmingham Newman University is a public university based in the suburb of Bartley Green in Birmingham, England. The university was founded in 1968 as Newman College of Higher Education. From 2008 to 2013, it was known as Newman University College, gaining full university status in 2013.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4e1e7b86-b62e-4c64-aec2-ac2e8ea51efc'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Leeds_Trinity_University_%28geograph_3395276%29.jpg/1280px-Leeds_Trinity_University_%28geograph_3395276%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: John Slater, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Leeds Trinity University is a public university in Horsforth, Leeds, West Yorkshire, England. Originally established to provide qualified teachers to Catholic schools, it gradually expanded and now offers foundation, undergraduate, and postgraduate degrees in a range of humanities and social sciences. Previously known as Leeds Trinity & All Saints, the institution became a university college in 2009 after gaining the right to award its own degrees, and was granted full university status in December 2012.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fc9cd755-1aae-486d-afdf-394431413b1f'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Bishop_Grosseteste_University.jpg/1280px-Bishop_Grosseteste_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paul Stainthorp, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Lincoln Bishop University, known until 2025 as Bishop Grosseteste University, is a public university in the city of Lincoln, England. LBU was established as a teacher training college for the Diocese of Lincoln in 1862. It gained taught degree awarding powers in 2012, applied for full university status, and was granted on 3 December 2012.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5028aad2-ef93-49fc-a5b1-d912b65e7c00'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/St_Katherine%27s_College%2C_Liverpool-2.jpg/1280px-St_Katherine%27s_College%2C_Liverpool-2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Rodhullandemu, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Liverpool Hope University is a public university with campuses in Liverpool, England. ‌The university grew out of three teacher training colleges: Saint Katharine's College, Notre Dame College and Christ's College. Uniquely in European higher education, the university is ecumenical, with Saint Katharine's College being Anglican and Notre Dame and Christ's Colleges being Catholic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2a60932d-50f8-4cce-86b3-27f3bd854ac2'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Northwesternhall.JPG/1280px-Northwesternhall.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cxnbs32, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Liverpool John Moores University is a public research university in the city of Liverpool, United Kingdom. The university can trace its origins to the Liverpool Mechanics' School of Arts, established in 1823. This later merged to become Liverpool Polytechnic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c7e5b00b-3c98-4941-9ebb-6c765089c0d5'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/London_Metropolitan_University_Logo.jpg/500px-London_Metropolitan_University_Logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: London Metropolitan University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Orion_Building_-Post_Graduate_Centre_of_London_Metropolitan_University-9June2009.jpg/1280px-Orion_Building_-Post_Graduate_Centre_of_London_Metropolitan_University-9June2009.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Alan Stanton, CC BY-SA 2.0, Wikimedia Commons$q$,$q$London Metropolitan University is a public research university in London, England. The University of North London and London Guildhall University merged in 2002 to create the university. The University's roots can be traced back to 1848.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ba9362a8-72d4-4170-b7e1-19abaea8ba72'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Lsbu-logo.svg/500px-Lsbu-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/d5/London_southbank_university.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Secretlondon at English Wikipedia., CC BY-SA 3.0, Wikimedia Commons$q$,$q$London South Bank University is a public university in Elephant and Castle, London. It is based in the London Borough of Southwark, near the South Bank of the River Thames, from which it takes its name. Founded in 1892 as the Borough Polytechnic Institute, it achieved university status in 1992 under the Further and Higher Education Act 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d5982cd4-0fb3-4fa1-81ee-664adaa912c6'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Shield_of_Loughborough_University.svg/500px-Shield_of_Loughborough_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nil pat13, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Loughborough_University_Entrance.jpg/1280px-Loughborough_University_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chick0nPTCG, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Loughborough University is a public research university in the market town of Loughborough, Leicestershire, England. It has been a university since 1966, but it dates back to 1909, when Loughborough Technical Institute was founded. In March 2013, the university announced it had bought the former broadcast centre at the Queen Elizabeth Olympic Park as a second campus.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('39412e88-a50b-4276-9f39-3edafa39aa61'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/1/13/Manchester_School_of_Art_Geograph_3735342.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: David Dixon, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Manchester Metropolitan University is a public university in Manchester, England. The university's predecessor, Manchester Polytechnic, gained university status in 1992. The university has 44,000 students and over 5,100 members of staff.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('20931b39-41df-4c17-834e-cffcc3f71e23'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/b/ba/Middlesex_University_Hendon_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Steve Cadman (stevecadman), CC BY-SA 2.0 uk, Wikimedia Commons$q$,$q$Middlesex University, branded as Middlesex University London, is a public research university based in Hendon, northwest London, England. The university also has campuses in Dubai and Mauritius. The university was in the historic county of Middlesex.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a38c2aea-79f7-4dbc-b92c-21ce5c59cb51'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/University_College_of_the_Arts%2C_Duke_St_-_geograph.org.uk_-_1398450.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Nigel Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Norwich University of the Arts is a public university in Norwich, Norfolk, United Kingdom that specialises in art, design, media, architecture and performance. It was founded as Norwich School of Design in 1845 and has a long history of arts education. It gained full university status in 2013.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4980c212-d9a5-4a5d-89c1-7bfa05c61427'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Logo_Nottingham_Trent_University.svg/500px-Logo_Nottingham_Trent_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Byron_house_2.JPG/1280px-Byron_house_2.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Superhasn at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Nottingham Trent University is a public research university located in Nottingham, England, which lies along the River Trent. Its origins date back to the establishment of the Nottingham Government School of Design in 1843, one of the earliest institutions of its kind in the United Kingdom. The university assumed its current status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2c488b63-d6f8-4559-9f19-eba5506931af'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/6/6a/Logo_colour_204px.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Nandana1981 at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/15/Oxford_brookes_headington_hill.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Donegalscott (talk), CC BY 1.0, Wikimedia Commons$q$,$q$Oxford Brookes University is a public university in Oxford, England. It is a post-1992 university, having received university status through the Further and Higher Education Act 1992. The university was named after its first principal, John Henry Brookes, who played a major role in the development of the institution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1cf18cd2-2cad-4afb-8f56-1b8e7b4d3522'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Wrexham_Glynd%C5%B5r_University_Logo.svg/500px-Wrexham_Glynd%C5%B5r_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Wrexham Glyndŵr University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/bc/Wrexham_Glyndwr_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Geoff Evans, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Wrexham University is a public university in the north-east of Wales, with campuses in Wrexham, Northop and St Asaph. It offers both undergraduate and postgraduate degrees, as well as professional courses. The university had 6,045 students in 2024/25.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5293886c-157c-4620-a66b-ff5b1cddf859'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Queen_Margaret_University_main_building.jpg/1280px-Queen_Margaret_University_main_building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Stuart Caie from Edinburgh, Scotland, CC BY 2.0, Wikimedia Commons$q$,$q$Queen Margaret University is a public university in Musselburgh, East Lothian, Scotland. It is named after Saint Margaret, Queen consort of Alba. The university can trace its origins to the Edinburgh School of Cookery and Domestic Science, founded in 1875.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ec2db1ae-597f-42d1-b3a8-f73e0525be86'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Queen_Mary_University_of_London_coat_of_arms.svg/500px-Queen_Mary_University_of_London_coat_of_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AlexD, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Queens%27_Building_%282899476115%29.jpg/1280px-Queens%27_Building_%282899476115%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ewan Munro from London, UK, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Queen Mary University of London is a public research university in London, England. It is a member institution of the federal University of London. Queen Mary is a member of the Russell Group of research-intensive British universities, the Association of Commonwealth Universities and Universities UK. Today, Queen Mary has six campuses across East and Central London in Mile End, Whitechapel, Charterhouse Square, Ilford, Lincoln's Inn Fields and West Smithfield, as well as an international presence in China, France, Greece and Malta.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('43354e7a-e947-4a4b-9109-6282a1472790'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Queen%27s_University_Belfast_arms.svg/500px-Queen%27s_University_Belfast_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Lanyon_Building%2C_Queen%27s_University%2C_Belfast.jpg/1280px-Lanyon_Building%2C_Queen%27s_University%2C_Belfast.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nick Birse, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Queen's University of Belfast, commonly known as Queen's University Belfast, is a public research university in Belfast, Northern Ireland. The university received its charter in 1845 as part of the Queen's University of Ireland and opened four years later, together with University of Galway and University College Cork. Queen's offers approximately 300 academic degree programmes at various levels.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ba192f08-58a1-4e38-a2f7-9fe75ebf0cbf'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/c/ca/University_of_Roehampton_logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Product1977, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Grove_House%2C_Roehampton_-_Diliff.jpg/1280px-Grove_House%2C_Roehampton_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Roehampton is a public research university in Roehampton, London. Founded as the Roehampton Institute of Higher Education, the university was established by four institutions, founded in the 19th century, which today make up the university's constituent colleges: Digby Stuart College, Froebel College, Southlands College and Whitelands College. Between 2000 and 2004, Roehampton, together with the University of Surrey, partnered as the Federal University of Surrey.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('116cb664-56cc-44ef-b914-84901da71147'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Exepos%C3%A9_Logo_2012_-_present_%28cropped%29.jpg/500px-Exepos%C3%A9_Logo_2012_-_present_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cryek, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/University_of_Exeter_Clock_tower.jpg/1280px-University_of_Exeter_Clock_tower.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Myself, Benjamin Evans, Public domain, Wikimedia Commons$q$,$q$The University of Exeter is a public research university in the West Country of England, with its main campus in Exeter, Devon. Its predecessor institutions, St Luke's College, Exeter School of Science, Exeter School of Art, and the Camborne School of Mines were established in 1838, 1855, 1863, and 1888 respectively. These institutions formed the University of Exeter when it received its royal charter in 1955.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('232da8e0-4beb-4cff-beda-e7ef293639cc'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/RoyalAg2.jpg/1280px-RoyalAg2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jongleur100, Public domain, Wikimedia Commons$q$,$q$The Royal Agricultural University, formerly the Royal Agricultural College, is a public university in Cirencester, Gloucestershire, England. Established in 1845, it was the first agricultural college in the English-speaking world.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d2dc287f-fd70-4fa2-b9a8-a94535227446'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Founder%27s_Building%2C_Royal_Holloway%2C_south_quad.jpg/1280px-Founder%27s_Building%2C_Royal_Holloway%2C_south_quad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Rwendland, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Royal Holloway, University of London, formally incorporated as Royal Holloway and Bedford New College, is a public research university and a member institution of the federal University of London. It has 3 faculties, 12 academic departments and approximately 10,500 undergraduate and postgraduate students from more than 100 countries. The campus is located west of Egham, Surrey, 19 miles from central London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fd0aae89-3a9a-4b50-b2b7-cbc265679516'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/c/cc/Royalvetcoll.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stephen McKay, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Royal Veterinary College is a veterinary school located in London and a member institution of the federal University of London. The RVC was founded in 1791 and joined the University of London in 1949. It is the oldest and largest veterinary school in the United Kingdom, and one of only 12 in the country where students can study to become a vet.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('db9eafae-1e59-46a1-a454-b5d99c453c6f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Sheffield_Hallam_University_logo.svg/500px-Sheffield_Hallam_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Sheffield Hallam University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/2/2f/SHU_buildings.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: St BC at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Sheffield Hallam University is a public research university in Sheffield, South Yorkshire, England. The university is based on two sites; the City Campus is located in the city centre near Sheffield railway station, while the Collegiate Crescent Campus is about two miles away in the Broomhall Estate off Ecclesall Road in south-west Sheffield. A third campus at Brent Cross Town in the London Borough of Barnet is expected to open for the 2025–2026 academic year.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('41dd8aa0-4acd-46fd-98b5-81b3f0bd5e5b'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Southampton-Solent-University-logo.svg/500px-Southampton-Solent-University-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Southampton Solent University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/e/e3/Eingang-SSU.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Paul Heimann (GoG at German Wikipedia), Public domain, Wikimedia Commons$q$,$q$Southampton Solent University is a public university based in Southampton, Hampshire, England. It has approximately 10,500 students. Its main campus is located on East Park Terrace near the city centre and the maritime hub of Southampton.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0dcd0365-b6b8-4b31-9d06-da7688de9fb0'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/4/40/St_Mary%27s_University_College_-_geograph.org.uk_-_1178912.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Colin Smith, CC BY-SA 2.0, Wikimedia Commons$q$,$q$St Mary's University is a public university in Strawberry Hill, Twickenham, in the London Borough of Richmond upon Thames. Established in 1850, it is the oldest Catholic university in the United Kingdom. The university received full university status in 2014 and has since expanded its academic portfolio, particularly in teacher education, sport science, health, and the humanities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a9d3f1d2-a69d-43ff-a540-2fba36a9da47'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Bay_Campus_Accommodation.jpg/1280px-Bay_Campus_Accommodation.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Swanseauni, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Swansea University is a public research university located in Swansea, Wales. It was established as University College of Swansea in 1920, as the fourth college of the University of Wales. In 1996, it changed its name to the University of Wales Swansea following structural changes within the University of Wales.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('aa972233-a746-48f5-8c82-a7db56b7dca1'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Teesside_University%27s_Phoenix_Building.JPG/1280px-Teesside_University%27s_Phoenix_Building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: LTees, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Teesside University is a public university with its main campus in Middlesbrough, North Yorkshire in North East England. It was officially opened as Constantine Technical College in 1930, before becoming a polytechnic in 1969, and finally granted university status in 1992 by the Privy Council. The university has over 22,500 students studying in the UK, according to the 2021/22 HESA student record.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d4454705-0bc2-47c8-932f-a6ecacfaee4a'::uuid,null,null,null,null,$q$University College Birmingham is a university in Birmingham, England. It was awarded full university status in 2012 along with Newman University. It is not a member of Universities UK. The university is situated in central Birmingham and offers both vocational and academic education at undergraduate and postgraduate levels, as well as some higher-level apprenticeships.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1ac08b8b-eb7d-4d56-8490-68fb3580f7e1'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/UCL_Crest.svg/500px-UCL_Crest.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AlexD, new version by Gnesener1900, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Wilkins_Building_1%2C_UCL%2C_London_-_Diliff.jpg/1280px-Wilkins_Building_1%2C_UCL%2C_London_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$University College London, which operates as UCL, is a public research university in London, England. It is a member institution of the federal University of London, and is the second-largest university in the United Kingdom by total enrolment and the largest by postgraduate enrolment. Established in 1826 as London University by founders who were inspired by the radical ideas of Jeremy Bentham, UCL was the first university institution to be established in London, and the first in England to be entirely secular and to admit students regardless of their religion.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c8b0c546-d338-40d4-9907-e4013f50db34'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/University_for_the_Creative_Arts_%28UCA%29_logo.png/500px-University_for_the_Creative_Arts_%28UCA%29_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: UniCreativeArts, CC BY 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/University_for_the_Creative_Arts%2C_Farnham%2C_Courtyard_Entrance.jpg/1280px-University_for_the_Creative_Arts%2C_Farnham%2C_Courtyard_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: BabelStone, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University for the Creative Arts is a specialist art and design university in Southern England. It was formed in 2005 as University College for the Creative Arts at Canterbury, Epsom, Farnham, Maidstone and Rochester when the Kent Institute of Art and Design was merged into the Surrey Institute of Art & Design, which already had degree-awarding status; both constituent schools had been formed by merging the local art schools, in Kent and Surrey respectively. It was granted university status in 2008, and the name changed to the present one.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('020fbf24-f98a-44fb-9f13-cd1362f203d5'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/University_of_Bath.jpg/1280px-University_of_Bath.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Bath is a public research university in Bath, England. Bath received its royal charter in 1966 as Bath University of Technology, along with a number of other institutions following the Robbins Report. Like the University of Bristol and University of the West of England, Bath traces its roots to the Merchant Venturers' Technical College, established as Bristol Trade School in 1856.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cb36622d-5e57-4ebd-ad31-a25574c4e9e8'::uuid,null,null,null,null,$q$The University of Bedfordshire is a public research university with campuses in Bedfordshire and Buckinghamshire, England. The university has roots in further and higher education from 1882: it gained university status in 1993 as the University of Luton. The university changed its name to the University of Bedfordshire in 2006, following the merger of the University of Luton with the Bedford campus of De Montfort University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('20c8103c-7381-4c05-abf6-dbdc42370a45'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Aston_Webb_buildings_in_snow%2C_The_University_of_Birmingham%2C_Dec_2009.jpg/1280px-Aston_Webb_buildings_in_snow%2C_The_University_of_Birmingham%2C_Dec_2009.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Simonham, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Birmingham is a public research university in Birmingham, England. It received its royal charter in 1900 as a successor to Queen's College, Birmingham, and Mason Science College, making it the first English redbrick university to receive its own royal charter, and the first English unitary university. It is a founding member of both the Russell Group of British research universities and the international network of research universities, Universitas 21.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0a596cd2-3060-40dc-9d23-37022cfedb9f'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/University_of_Bradford_Richmond_24_April_2017_01.jpg/1280px-University_of_Bradford_Richmond_24_April_2017_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Bradford is a public research university located in the city of Bradford, West Yorkshire, England. A plate glass university, it received its royal charter in 1966, making it the 40th university to be created in Britain, but can trace its origins back to the establishment of the industrial West Yorkshire town's Mechanics Institute in 1832. Known for its research, inclusivity and careers support for students, it has been named England's top university for social mobility five years in a row.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1c9af7e8-0fe3-4067-8a71-4fff11458c0a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/University_of_Brighton_logo.svg/500px-University_of_Brighton_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Brighton, Public domain, Wikimedia Commons$q$,null,null,$q$The University of Brighton is a public university based in Brighton on the south coast of England. Its roots can be traced back to 1858 when the Brighton School of Art was opened in the Royal Pavilion. It achieved university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('30a59794-2f18-42d6-a864-1fc218fc68ec'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/University_of_Bristol.jpg/1280px-University_of_Bristol.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Simon Cobb, CC0, Wikimedia Commons$q$,$q$The University of Bristol is a public research university in Bristol, England. It received its royal charter in 1909, although it can trace its roots to University College, Bristol, established in 1876. Bristol Medical School, founded in 1833, was merged with the university college in 1893, and later became the university's school of medicine.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5aa969fc-1862-4666-a720-7de98a1771c5'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/c/c6/University_of_Chester_-_geograph.org.uk_-_1331802.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Dennis Turner, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Chester is a public university located in Chester, England. The university originated as the first purpose-built teacher training college in the UK. As a university, it now occupies seven campus sites in and around Chester, one in Warrington, and a University Centre in Birkenhead. It offers a range of foundation, undergraduate and postgraduate courses, as well as undertaking academic research.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('85be42b0-0357-4d7a-a226-2f3666bdff91'::uuid,null,null,null,null,$q$The University of Chichester is a public university located in West Sussex, England, which became a university in 2005. Campuses are based in the city of Chichester and the nearby coastal resort of Bognor Regis and an associate campus for commercial music on the Isle of Wight. The University of Chichester has 14 departments, with specialisms including Humanities, Sport, Musical Theatre, Acting and Education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2f72d4ab-31a5-4553-8690-ccf1e09ede1e'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/6/6d/Skiddaw_Building%2C_University_of_Cumbria_-_geograph.org.uk_-_715574.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Rose and Trev Clough, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Cumbria is a public university in Cumbria, with its headquarters in Carlisle and other major campuses in Lancaster, Ambleside, and London. It has roots extending back to the Society for the Encouragement of Fine Arts, established in 1822, and the teacher training college established by Charlotte Mason in the 1890s. It opened its doors in 2007 as a university.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('320c02e9-ef52-430e-885f-d1d10c6214d8'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/University_of_Derby_Library.jpg/1280px-University_of_Derby_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Lianne99, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Derby, formerly known as Derby College, is a public university in the city of Derby, England. It traces its history back to the establishment of the Derby Diocesan Institution for the training of schoolmistresses in 1851. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7dc2f30c-b488-4bd0-a09a-73febcb0b6b1'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Dundee_University_Scrymgeour.jpg/1280px-Dundee_University_Scrymgeour.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ydam, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Dundee is a public research university located in the city of Dundee, Scotland. It was founded as a university college in 1881 with a donation from the prominent Baxter family of textile manufacturers. The institution was, for most of its early existence, a constituent college of the University of St Andrews alongside United College and St Mary's College located in the town of St Andrews itself.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('83cb8ef5-8dcd-4dc1-932a-abfa36aaf51e'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Durham_-_Castle_-_02.jpg/1280px-Durham_-_Castle_-_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Benjamin Smith, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Durham, which operates under the trading name of Durham University, is a collegiate public research university in Durham, England, founded by an Act of Parliament in 1832 and incorporated by royal charter in 1837. It was the first recognised university to open in England for more than 600 years, after Oxford and Cambridge, and is thus identified by historians as the third-oldest university in England. As a collegiate university, its main functions are divided between the academic departments of the university and its 17 colleges.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ebb63931-52cf-4694-835c-381d2e1daa07'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/1/1a/School_of_World_Art_Studies.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: IWAM2009, CC0, Wikimedia Commons$q$,$q$The University of East Anglia is a public research university in Norwich, England. Established in 1963 on a 360-acre campus west of the city centre, the university has four faculties and twenty-six schools of study. It is one of five BBSRC funded research campuses, with forty businesses, four independent research institutes and a teaching hospital on site.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c38015a2-293b-4a2a-9a98-10da18f519b8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/University_of_East_London_logo.svg/500px-University_of_East_London_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/40/University_of_East_London_-_geograph.org.uk_-_54115.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Glyn Baker, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of East London is a public university located in the London Borough of Newham, London, England, based at three campuses in Stratford and Docklands, following the opening of University Square Stratford in September 2013. The University of East London began as the West Ham Technical Institute and it was officially opened in October 1898 after approval was given for the construction of the site by the West Ham Technical Instruction Act Committee in 1892 following the Technical Instruction Act 1889. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d438a1a9-bb01-48da-9498-a21c94aa64cc'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/University_of_Essex_logo.svg/500px-University_of_Essex_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Essex, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/University_of_Essex_-_Albert_Sloman_Library.png/1280px-University_of_Essex_-_Albert_Sloman_Library.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Goosta, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Essex is a public research university in Essex, England. Established by royal charter in 1965, it is one of the original plate glass universities. The university comprises two campuses in the county, one in Loughton with its primary campus in Wivenhoe Park, Colchester.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('08cad281-3c20-4811-a4c0-df538a979164'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/5/56/Bolton_University_-_Deane_campus_-_geograph.org.uk_-_109397.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Margaret Clough, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Greater Manchester is a public university in Bolton, Greater Manchester in England. It was known as the University of Bolton from 2005 until 2024. The university is commonly referred to as a 'post-92' institution, which is a reference to the Further and Higher Education Act 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c31825d7-efe2-440c-a94e-7a92cd6b57de'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/United_Kingdom_-_England_-_London_-_Greenwich_-_Old_Royal_Naval_College.jpg/1280px-United_Kingdom_-_England_-_London_-_Greenwich_-_Old_Royal_Naval_College.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: C. G. P. Grey, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Greenwich is a university within the London and South East University Group in Greenwich, England. It was an independent university from 1992 to 2026, when it merged with the University of Kent to form LASE. Following the merger, Greenwich became an academic division within LASE, operating under the branding of the University of Greenwich, while LASE's academic board became responsible for the admission of students, teaching and granting degrees. However, students apply to, are taught at, and receive degrees in the name of, the University of Greenwich.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ae23a315-1132-4709-a125-80d473499cfc'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/University_of_Hertfordshire_Logo.svg/500px-University_of_Hertfordshire_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Hertfordshire, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/UHCollegeLaneCampus.jpg/1280px-UHCollegeLaneCampus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: en:User:Jknabe and de:User:Jknabe, Public domain, Wikimedia Commons$q$,$q$The University of Hertfordshire is a public research university in Hertfordshire, United Kingdom. It is based primarily in Hatfield, Hertfordshire. Its antecedent institution, Hatfield Technical College, was founded in 1948 and was identified as one of 25 Colleges of Technology in the United Kingdom in 1959.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('da3b0516-be39-4d1b-a1da-8bae26376479'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/b/b9/HuddunimainmarqueRGB.gif?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University Of Huddersfield, CC BY 3.0, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/43/Queensgate_Campus_Top.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University Of Huddersfield, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Huddersfield is a public research university located in Huddersfield, West Yorkshire, England. It has been a University since 1992, but has its origins in a series of institutions dating back to the 19th century. It has made teaching quality a particular focus of its activities, winning the inaugural Higher Education Academy Global Teaching Excellence Award in 2017, and achieving a Teaching Excellence Framework Gold Award, in 2017 and 2023.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('912da2b5-27ca-464f-8917-3b1fda7d4c98'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/University_of_Hull_arms.svg/500px-University_of_Hull_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hogweard, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/61/Venn_Building%2C_University_of_Hull.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stephen Horncastle, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Hull is a public research university in Kingston upon Hull, a city in the East Riding of Yorkshire, England. It was founded in 1927 as University College Hull. The main university campus is located in Hull and is home to the Hull York Medical School, a joint initiative with the University of York.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ad798243-2d5f-4884-ae45-5d9d2f402005'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Keele_University_Library.jpg/1280px-Keele_University_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jonathan Hutchins, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Keele University is a public research university in Keele, Staffordshire, England. Originally established in 1949 as the University College of North Staffordshire, it received university status through a Royal Charter in 1962, becoming the University of Keele. The university pioneered the UK's dual honours degree system, offering students the chance to study two subjects together.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('70cabf26-596b-46c2-9a8f-7742bbd9776c'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/School_of_Arts_-_UKC.JPG/1280px-School_of_Arts_-_UKC.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: St BC (talk), CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Kent is a university within the London and South East University Group in Kent, England. It was an independent university from 1965, when it was founded by royal charter, to 2026, when it merged with the University of Greenwich to form LASE. Following the merger, Kent became an academic division within LASE, operating under the branding of the University of Kent, while LASE's academic board became responsible for the admission of students, teaching and granting degrees. However, students apply to, are taught at, and receive degrees in the name of, the University of Kent.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4bfd381e-8ae5-4747-bc35-b4934098e585'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Parkinson_Building%2C_Leeds_University%2C_England-12Sept2010.jpg/1280px-Parkinson_Building%2C_Leeds_University%2C_England-12Sept2010.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tim Green from Bradford, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Leeds is a public research university in Leeds, West Yorkshire, England. It was established in 1874 as the Yorkshire College of Science. In 1884, it merged with the Leeds School of Medicine and was renamed Yorkshire College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('14a32f01-da3b-4ca2-adc0-aa728d19ff2e'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/University_of_Leicester_towers_2010.jpg/1280px-University_of_Leicester_towers_2010.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: NotFromUtrecht, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Leicester is a public research university based in Leicester, England. It was established as a university college in 1921. In 1957, the university's predecessor, University College, Leicester, gained university status by royal charter.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('309bee15-3f31-471a-a41b-6e51c252a7d5'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/University_of_Lincoln.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: H2d92, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Lincoln is a public research university in Lincoln, England, with origins dating back to 1861. It gained university status in 1992 and its present name in 2001. The main campus is in the heart of the city of Lincoln alongside the Brayford Pool.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('05eb69e7-21dd-43c0-a30d-20cf349c46a6'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/University_of_Liverpool_Building.jpg/1280px-University_of_Liverpool_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: User:Chowells, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Liverpool is a public research university in Liverpool, England. Founded in 1881 as University College Liverpool and affiliated with Victoria University in 1884, it received a royal charter from King Edward VII in 1903, thereby attaining the authority to award degrees independently. The university holds and operates assets on the National Heritage List, such as the Liverpool Royal Infirmary, the Ness Botanic Gardens, and the Victoria Gallery & Museum.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('b9027acc-56c3-47da-9320-2b2a37a60169'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Manchester_University_Logo_%282%29.png/500px-Manchester_University_Logo_%282%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Whitworth_Hall.jpg/1280px-Whitworth_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: DrPhoenix, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Manchester is a public research university in Manchester, England, with its main campus south of the city centre on Oxford Road. It is a red brick university, a product of the civic university movement of the late 19th century. The current institution was formed in 2004 through the merger of the University of Manchester Institute of Science and Technology and the Victoria University of Manchester.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('909aeeb6-711a-4126-9a2d-16b9d55fd559'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Ncle_Union_2012.jpg/1280px-Ncle_Union_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Newcastle upon Tyne, which trades as Newcastle University, is a public research university based in Newcastle upon Tyne, England. It has overseas campuses in Singapore and Malaysia. The university is a red brick university and a founding member of the Russell Group, an association of research-intensive UK universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('52c33587-b13a-4e4c-8216-2419db331ddb'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/UoN_Newton.jpg/1280px-UoN_Newton.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: StJaBe, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Northampton is a public university based in Northampton, Northamptonshire, England. It was formed in 1975 as Nene College of Higher Education by the amalgamation of a number of training colleges and gained university college status as University College Northampton in 1999 and full university status as the University of Northampton in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f02b428f-c2d4-41c1-a35d-c171b3d32155'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Northumbria_University_%28geograph_2248224%29.jpg/1280px-Northumbria_University_%28geograph_2248224%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Peter McDermott, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Northumbria at Newcastle, which operates as Northumbria University, is a public research university located in Newcastle upon Tyne, North East of England. It has been a university since 1992, but has its origins in the Rutherford College, founded in 1877. Northumbria University is primarily based within City Campus located in Newcastle upon Tyne city centre and at Coach Lane campus on the outskirts of the city centre, London and Amsterdam.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4dca123b-9db3-472f-b2dd-30458b913969'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Nottingham%2C_Trent_Building.jpg/1280px-Nottingham%2C_Trent_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Greentreepencil, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Nottingham is a public research university in Nottingham, England. It was founded as University College Nottingham in 1881, and was granted a royal charter as a university in 1948. Nottingham's main campus, the Jubilee Campus and the main teaching hospital are located within the City of Nottingham, with a number of smaller campuses and sites elsewhere in Nottinghamshire and Derbyshire.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bfabc276-11ff-4d07-b003-40ab7fbe27f2'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/d/d7/University_of_Plymouth_Arts_Block.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Tony Atkin, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Plymouth is a public research university based predominantly in Plymouth, England, where the main campus is located, but the university has campuses and affiliated colleges across South West England. With 18,410 students, it is the 57th largest in the United Kingdom by total number of students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d162b3af-a079-4915-979e-af94a39e5433'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/University_of_Portsmouth_Logo.png/500px-University_of_Portsmouth_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Critical Hippo, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/University_of_Portsmouth_Dennis_Sciama_building.JPG/1280px-University_of_Portsmouth_Dennis_Sciama_building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Editor5807, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Portsmouth is a public university in Portsmouth, England. Its institutional origins trace back to 1870 with the establishment of the Portsmouth and Gosport School of Science and Art. Over the subsequent decades, the institution underwent a series of organisational transformations, becoming Portsmouth Polytechnic in 1969 before gaining university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bf7f3aa8-1973-4e6b-937a-e58e675b94a5'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/4/41/St_Andrews_University_Classics_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of St Andrews is a public research university in the town of St Andrews in Scotland. It is the oldest of the four ancient universities of Scotland and, following the universities of Oxford and Cambridge, the third-oldest university in the English-speaking world. St Andrews was founded in 1413 when the Antipope Benedict XIII issued a papal bull to a small founding group of Augustinian clergy.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('903e25ca-e816-4b7d-95e9-a2ed711f1a94'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/University_of_Reading_arms.svg/500px-University_of_Reading_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hogweard, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/3a/The_University_of_Reading.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Andrew Smith, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Reading is a public research university in Reading, Berkshire, England. It was founded in 1892 as the University Extension College, Reading, an extension college of Christ Church, Oxford, and became University College, Reading in 1902. The institution became a university with the power to grant its own degrees in 1926 by royal charter from King George V, and was the only university to receive such a charter between the two world wars.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e31eb188-42d1-47b1-baa3-1a539cd7f7d4'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/e/e7/University_of_Salford_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University of Salford, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/University_of_Salford.jpg/1280px-University_of_Salford.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paul Stainthorp, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Salford is a public research university located in Salford, Greater Manchester, England, 1 mile west of Manchester city centre. The Royal Technical Institute, Salford, which opened in 1896, became a College of Advanced Technology in 1956 and gained university status in 1967, following the Robbins Report into higher education. It has 26,030 students and is in 160 acres of parkland on the banks of the River Irwell.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('89e22c5f-e246-4816-87e8-d61fdb064af4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Shield_of_the_University_of_Sheffield.svg/500px-Shield_of_the_University_of_Sheffield.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Sir_Frederick_Mappin_Building.jpg/1280px-Sir_Frederick_Mappin_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paolo Margari from Sheffield, United Kingdom / Italy, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Sheffield is a public research university in Sheffield, South Yorkshire, England. Its history traces back to the foundation of Sheffield Medical School in 1828, Firth College in 1879 and Sheffield Technical School in 1884. The University College of Sheffield was subsequently formed by the amalgamation of the three institutions in 1897.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('26e1f3b5-b007-4ef4-8b63-381c2fb3a040'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Logo_of_University_of_South_Wales.svg/500px-Logo_of_University_of_South_Wales.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of South Wales, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/University_of_South_Wales%2C_Newport_city_centre_campus.jpg/1280px-University_of_South_Wales%2C_Newport_city_centre_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pwimageglow, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of South Wales is a public university in Wales, with campuses in Cardiff, Newport and Pontypridd. It was formed on 11 April 2013 from the merger of the University of Glamorgan and the University of Wales, Newport. The university is the second largest university in Wales in terms of its student numbers, and offers over 300 undergraduate and postgraduate courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4b1603eb-750f-41f4-b89b-d26f9cb406e4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/University_of_Southampton_Logo.svg/500px-University_of_Southampton_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Southampton, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/HartleyLibraryFront.JPG/1280px-HartleyLibraryFront.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Iamtheabelman, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Southampton is a public research university in Southampton, England. Southampton is a founding member of the Russell Group of research-intensive universities in the United Kingdom. The university has seven campuses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('46099416-2b93-4080-83e2-92a62c95824c'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/UniSSoM.jpg/1280px-UniSSoM.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mark Boyce, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Surrey is a public research university in Guildford, Surrey, England. The university received its royal charter in 1966, along with a number of other institutions following recommendations in the Robbins Report. The institution was previously known as Battersea College of Technology and was in Battersea Park, London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7378d03b-2904-41f3-ac6d-d52c5be57021'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/University_of_Sussex_Logo.svg/500px-University_of_Sussex_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Sussex, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Universit%C3%A4t_Sussex.jpg/1280px-Universit%C3%A4t_Sussex.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Uploaded on November 13, 2005; by TimBrighton, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Sussex is a public research university located in Falmer, East Sussex, England. It lies mostly within the city boundaries of Brighton and Hove. Its large campus site is surrounded by the South Downs National Park, and provides convenient access to central Brighton 5.5 kilometres away.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('de08453b-50a7-4038-a357-c890ad821fb2'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/University_of_the_Arts_London%2C_Central_Services_Entrance.jpg/1280px-University_of_the_Arts_London%2C_Central_Services_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ualwebsupport, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of the Arts London is a public collegiate university in London, England, United Kingdom. It specialises in the arts, design, fashion, and the performing arts. The university is a federation of six arts colleges: Camberwell College of Arts, Central Saint Martins, Chelsea College of Arts, the London College of Communication, the London College of Fashion, and Wimbledon College of Arts.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('73a2eece-af4a-4b2b-bd36-b6cc4bb7388c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/UWE_Bristol_logo.svg/500px-UWE_Bristol_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of the West of England, Bristol, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/a/a8/Uwe.bristol.750pix.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Arpingstone at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$The University of the West of England, also known as UWE Bristol, is a public research university, located in and around Bristol, England. With over 37,000 students and 4,200 staff, it is the largest provider of higher education in the South West of England. The institution was formed as Bristol Polytechnic in 1970 and received university status in 1992, becaming the University of the West of England, Bristol.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a027ce5a-c15c-4860-be00-bf1519498d98'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/University_of_the_West_of_Scotland_Logo.svg/500px-University_of_the_West_of_Scotland_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of the West of Scotland, Public domain, Wikimedia Commons$q$,null,null,$q$The University of the West of Scotland, formerly the University of Paisley, is a public university with four campuses in south-western Scotland, in the towns of Paisley, Blantyre, Dumfries and Ayr, as well as a campus in London, England. The present institution dates from August 2007, following the merger of the University of Paisley with Bell College, Hamilton. It can trace its roots to the late 19th century, and has undergone numerous name changes and mergers over the last century, reflecting its gradual expansion throughout the west of Scotland region.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('84d64601-96fa-452e-825e-f295d2240b4e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/University_of_Ulster_logo.svg/500px-University_of_Ulster_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/University_of_Ulster%2C_Belfast_Campus%2C_July_2010_%2807%29.JPG/1280px-University_of_Ulster%2C_Belfast_Campus%2C_July_2010_%2807%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ardfern, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Ulster University, legally the University of Ulster, is a multi-campus public research university located in Northern Ireland. It is often referred to informally and unofficially as Ulster, or by the abbreviation UU. It is the largest university in Northern Ireland and the second-largest university on the island of Ireland, after the federal National University of Ireland. Established in 1865 as Magee College, the college took its modern form in 1984 after the merger of the New University of Ulster established in 1968, and Ulster Polytechnic, incorporating its four Northern Irish campuses under the University of Ulster banner.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f8c35a8a-f1a8-494f-9e4a-951fbf4623c7'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/8/8f/University_of_Wales%2C_Lampeter._-_geograph.org.uk_-_423417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: RHYS WILLIAMS, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Wales Trinity Saint David is a public university with campuses in Carmarthen, Swansea, Cardiff, Birmingham and London. The university came into existence through the merger of the two oldest higher education institutions in Wales, the University of Wales, Lampeter and Trinity University College in 2010, under Lampeter's royal charter of 1828. In 2011, it was announced that the University of Wales would also merge into Trinity Saint David.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('b8398d6d-a234-46e9-b275-1d447d3a7d8f'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/TVU_Paragon_Campus_Brentford.jpg/1280px-TVU_Paragon_Campus_Brentford.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Sansmalrst, Public domain, Wikimedia Commons$q$,$q$The University of West London is a public research university in England, with campuses in Ealing, Brentford and Reading, Berkshire. The university has roots in 1860 when the Lady Byron School was founded, later Ealing College of Higher Education. In 1992, the then-named Polytechnic of West London became a university as Thames Valley University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7e6073de-bc9b-4cce-b07e-449822283df2'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/University_of_Westminster_Logo.svg/500px-University_of_Westminster_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Westminster, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b8/University_of_Westminster%2C_Harrow_Campus_-_geograph.org.uk_-_98048.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: David Hawgood, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Westminster is a public university based in London, United Kingdom. Founded in 1838 as the Royal Polytechnic Institution, it was the first polytechnic to open in London. The Polytechnic formally received a Royal charter in August 1839, and became the University of Westminster in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e5852981-8d2d-4dc6-8d26-26a843ad3ed1'::uuid,null,null,null,null,$q$The University of Winchester is a public research university based in the city of Winchester, Hampshire, England. The university has origins tracing back to 1840 as a teacher training college, but was established in 2005. Winchester University is a member of The Cathedrals Group, an association of universities and university colleges in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e4397bda-a1a0-4c7a-8716-138fecd42494'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/3b/University_of_Wolverhampton_-_geograph.org.uk_-_396324.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Gordon Griffiths, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Wolverhampton is a public university in Wolverhampton, England, located on four campuses across the West Midlands, Shropshire and Staffordshire. Originally founded in 1827 as the Wolverhampton Tradesmen's and Mechanics' Institute, the university was subject to a series of merges, incorporations, and expansions with other local colleges, one of which occurred under the supervision of Prince George, Duke of Kent. The university has four faculties comprising eighteen schools and institutes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e1ad4597-7939-492b-aed9-2bd9d11f4cdb'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/The_Hive_-_Worcester_%2827415265175%29.jpg/1280px-The_Hive_-_Worcester_%2827415265175%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Esther Westerveld from Haarlemmermeer, Nederland, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Worcester is a public research university, based in Worcester, England. With a history dating back to 1946, the university began awarding degrees in 1997 and was granted full university status in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('94818231-694c-4573-9223-01f1535f21c2'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/York_central_hall.jpg/1280px-York_central_hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Johnteslade at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of York is a collegiate public research university in York, England. Established in 1963, the university has expanded to more than thirty departments and centres, covering a wide range of subjects. South-east of the city of York, the university campus is about 500 acres in size.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4d7be9d4-3e18-40df-99bc-8c6b5bc2e04c'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/York_St_John_University.jpg/1280px-York_St_John_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Robert Dawson, CC BY-SA 4.0, Wikimedia Commons$q$,$q$York St John University, often abbreviated to YSJ, is a public university located on a large urban campus in York, England. Established in 1841, it achieved university status in 2006 and in 2015 was given research degree awarding powers for PhD and other doctoral programmes. It is one of several higher education institutions which have religious foundations and is part of the Cathedrals Group of Universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('20a424cf-dc55-400e-94ef-bd6a16432f36'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Logo_University_of_the_Sunshine_Coast.svg/500px-Logo_University_of_the_Sunshine_Coast.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of the Sunshine Coast, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/University_of_the_Sunshine_Coast_Campus.jpg/1280px-University_of_the_Sunshine_Coast_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tekhenu, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of the Sunshine Coast is a public university based on the Sunshine Coast, Queensland, Australia. After opening with 524 students in 1996 as the Sunshine Coast University College, it was later renamed the University of the Sunshine Coast in 1999. The university has a flagship campus at Sippy Downs on the Sunshine Coast, with more campuses at Hervey Bay on the Fraser Coast, Gympie, and Caboolture.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('524eccdb-dee6-4428-9c76-010546907c50'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/b/b9/Normal_Booloominbah_Night.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: David Elkins, Public domain, Wikimedia Commons$q$,$q$The University of New England is a public university in the New England region of the state of New South Wales, Australia. Founded in 1938, it was the first Australian university to be established outside of a state capital. Its main campus is located in the regional city of Armidale mid-way between Sydney and Brisbane.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4551d6e0-f607-4048-9a1c-626663fad4d7'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Monashcaulfield2.jpg/1280px-Monashcaulfield2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: No machine-readable author provided. Firmatic assumed (based on copyright claims, Public domain, Wikimedia Commons$q$,$q$Monash University is a public research university based in Melbourne, Victoria, Australia. Named after World War I general Sir John Monash, it was founded in 1958. The university has a number of campuses, four of which are in Victoria, one in Malaysia and another one in Indonesia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5a765466-b63c-42bb-830c-8207147d2d33'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/La_Trobe_University.jpg/1280px-La_Trobe_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Phil Lees, CC BY-SA 2.0, Wikimedia Commons$q$,$q$La Trobe University is a public research university based in Melbourne, Victoria, Australia. Its main campus is located in the suburb of Bundoora. The university was established in 1964, becoming the third university in the state of Victoria and the twelfth university in Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('81a7ae98-0b15-44d0-a4f1-8053f50f9b83'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/University_House_ANU_Canberra_%282948649223%29.jpg/1280px-University_House_ANU_Canberra_%282948649223%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dave Snowden, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Australian National University is a public research university and member of the Group of Eight, located in Canberra, the capital of Australia. Its main campus in Acton encompasses seven teaching and research colleges, in addition to several national academies and institutes. Established in 1946, ANU is the only university to have been created by the Parliament of Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bd1bcfc2-1093-4670-922a-47281070e05b'::uuid,null,null,null,null,$q$Canning College is a specialist education institution delivering programs that provide local and international students with pathways into universities. It delivers programs for Year 10, Year 11, Year 12, Certificate IV and Diploma of Commerce. Canning College is located on Marquis Street in Bentley, a suburb situated seven kilometres south-east of Perth, Western Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f871192e-17fa-4e8f-b0b7-c039cd875244'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/CQU_Engineering_building.jpg/1280px-CQU_Engineering_building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: RegionalQueenslander, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Central Queensland University is an Australian public university based in central Queensland. CQUniversity is the only Australian university with a campus presence in every mainland state. Its main campus is at Norman Gardens in Rockhampton, however, it also has campuses in Adelaide, Brisbane, Bundaberg, Cairns, Emerald, Gladstone, Mackay, Melbourne, Noosa, Perth, Rockhampton City, Sydney and Townsville.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('de6dc923-0e94-4878-b8c7-74751b64a383'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/CDU_library%2C_Casuarina.jpg/1280px-CDU_library%2C_Casuarina.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Stephen Barnett from Darwin, Australia, CC BY 2.0, Wikimedia Commons$q$,$q$Charles Darwin University is an Australian public university with two campuses in Darwin and six satellite campuses in metropolitan and regional areas of the Northern Territory and New South Wales. It was established in 2003 after the merger of Northern Territory University, the Menzies School of Health Research, and Centralian College. It is the largest tertiary education provider in the Northern Territory and the first dual-sector university in Australia, offering both academic degree and vocational education programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e16dbd62-cde3-4e7a-b122-fb62347457d0'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/CSU_South_Wagga_Campus_-_Kay_Hull_Veterinary_Teaching_Hospital_1.jpg/1280px-CSU_South_Wagga_Campus_-_Kay_Hull_Veterinary_Teaching_Hospital_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bidgee, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Charles Sturt University is an Australian multi-campus public university located in New South Wales, Australian Capital Territory and Victoria. Established in 1989, it was named in honour of Captain Charles Sturt, a British explorer who made expeditions into regional New South Wales and South Australia. It is the largest regional university in Australia, offering a multidisciplinary spectrum of courses in collaboration with various partners across the country.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a03a3830-25dc-46aa-a8b1-f5a222355056'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/f/f2/Deakin_Worldly_Strip_Logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Deakin University, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Deakin_University_Burwood_Campus.jpg/1280px-Deakin_University_Burwood_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Donaldytong, Public domain, Wikimedia Commons$q$,$q$Deakin University is a public research university in the state of Victoria, Australia. Its largest campus is in Victoria's state capital Melbourne, with regional campuses in Geelong and Warrnambool. The university was named after Alfred Deakin, the early Prime Minister of Australia and a founding father of Australian Federation.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('846d80a6-644e-4318-8978-426e3ebd68f1'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/9/9c/Edith_Cowan_University_Joondalup_library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Michael Coghlan from Adelaide, Australia, CC BY 2.0, Wikimedia Commons$q$,$q$Edith Cowan University is a public research university in Western Australia. It is named in honour of Edith Cowan, the first woman to be elected to an Australian parliament. It is the second-largest university in the state with over 30,000 students in 2023.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f6bfdb8d-f474-4b8c-9b34-e747ace18030'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/University_of_ballarat_city_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: No machine-readable author provided. Powerek38 assumed (based on copyright claim, Public domain, Wikimedia Commons$q$,$q$Federation University Australia is a public university based in Victoria, Australia. It is the modern descendant of the School of Mines Ballarat, established in 1870 as the fourth tertiary institution in Australia, which evolved to form the modern university as it is today. Formerly known as the University of Ballarat, it changed its name to Federation University in 2014 as it became a multi-campus institution with a strong presence both in Ballarat and across the state.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('01a72651-9656-4237-8efd-813a720a2221'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Flinders_from_hill.jpg/1280px-Flinders_from_hill.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cyberjunkie, CC BY 2.5, Wikimedia Commons$q$,$q$Flinders University, established as the Flinders University of South Australia, is an Australian public research university based in Adelaide, South Australia. Founded in 1966, it was named in honour of the British navigator Matthew Flinders, who had explored and surveyed the Australian coastline in the early 19th century. Flinders University became the oldest extant South Australian university, superseding the University of Adelaide, when the latter merged with the University of South Australia to create Adelaide University in early 2026.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d1c6019e-fbf8-40cf-9142-4a7d90eb713f'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/4/4c/Gordon_institute_of_tafe_building%2C_geelong.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Marcus Wong Wongm, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Gordon Institute of TAFE is the Technical and Further Education institute predominantly servicing the wider Geelong area in Victoria, Australia. The Gordon opened in 1887 and celebrated 130 years of providing education in 2017. The Gordon provides education to more than 13,500 students annually and, with more than 500 staff members, it is one of the largest employers in Geelong.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('81ed3c1f-50b6-4679-ac13-a35d8faec1e9'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/b/b4/Griffith_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: www.brisbaneishome.com, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Griffith University is a public research university in South East Queensland, Australia. The university was founded in 1971 and officially opened in 1975. The university has five campuses, at Gold Coast, Nathan, Logan, South Bank, and Mount Gravatt.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('15670e99-f1a7-46b5-a6cd-6b215d614c11'::uuid,null,null,null,null,$q$Holmesglen Institute is a vocational education and higher education institute situated primarily in the South-Eastern suburbs of Melbourne, Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('19bea5fb-8c84-409b-a894-68c5fae84a29'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/JCU_Entrance.jpg/1280px-JCU_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nielg, Public domain, Wikimedia Commons$q$,$q$James Cook University is a public university in North Queensland, Australia. The second oldest university in Queensland, JCU is a teaching and research institution. The university's main campuses are located in the tropical cities of Cairns and Townsville, and one in the city state of Singapore.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7db0f748-add7-4a85-96e9-dcb8f596a6a9'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Macquarie_University_International_brandmark_%E2%80%93_Horizontal_configuration.svg/500px-Macquarie_University_International_brandmark_%E2%80%93_Horizontal_configuration.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Macquarie University, CC0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Macquarie_University_New_Library_2011.jpg/1280px-Macquarie_University_New_Library_2011.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mw12310, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Macquarie University is a public research university in Sydney, New South Wales, Australia. A research-intensive university, in 2023 it had 44,000 students. The university's main campus is at Wallumattagal, in the Sydney suburb of Macquarie Park, which is served by Macquarie University railway station.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('846e2f05-115a-4cc9-b3ec-b24b4974d2dc'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/NMIT_Preston_building_B.jpg/1280px-NMIT_Preston_building_B.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tirin also known as Takver (www.takver.com), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Melbourne Polytechnic, formerly NMIT, is an institute of higher education and vocational education located in Melbourne, Australia that has been operating since 1912, and aided by a $19 million grant from the Victorian Government. A wide selection of study options in vocational education are offered from short courses, pre-apprenticeships, apprenticeships, and traineeships through to certificates, diplomas, advanced diplomas, and onto higher education, tertiary degrees under the Australian Qualifications Framework. In 2013, there were 511 Full Time Equivalent teaching staff and 348.5 support staff employed by Melbourne Polytechnic delivering over 500 courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0cffc127-e633-43db-a21c-5fac7482204f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Murdoch_University_extended_logo.png/500px-Murdoch_University_extended_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AOMBG89HZMBK3H6, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Chancellery_Building.jpg/1280px-Chancellery_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Michal Lewi, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Murdoch University is a public university in Perth, Western Australia, with additional campuses in Singapore and Dubai. It began operations as the state's second university on 25 July 1973, and accepted its first undergraduate students in 1975. Its name is taken from Walter Murdoch, the Founding Professor of English and former Chancellor of the University of Western Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('147976c3-639e-40fd-af30-eeb1521db089'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/1/17/QUT_KG_CtoA.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Silje Ljosland Bakke - Silje at Norwegian Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Queensland University of Technology is a public research university located in the city of Brisbane in Queensland, Australia. It has two major campuses, a city campus in Gardens Point and a campus in Kelvin Grove. The university offers courses in fields including architecture, engineering, information technology, healthcare, teaching, law, arts and design, science and mathematics.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e29f7921-fc63-463f-95d8-3802648f9870'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/RMIT_University_Logo.svg/500px-RMIT_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/RMIT_University_Building_01.jpg/1280px-RMIT_University_Building_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Donaldytong, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Royal Melbourne Institute of Technology is a public research university located in the city of Melbourne in Victoria, Australia. Proposed by Francis Ormond, and established in 1887 by Ormond, the Victorian government, Trades Hall Council and others, it is the seventh-oldest institution of higher education in Australia, a founding member of the Australian Technology Network, and a member of Universities Australia. RMIT began as a night school offering classes in art, science and technology in response to the Industrial Revolution in Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('178384cb-0bff-4995-b85d-43cc360ae49e'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/c/c0/Southern_Cross_vertical.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Logo: Swerve, CC BY-SA 4.0, Wikimedia Commons$q$,null,null,$q$Southern Cross University is an Australian public university, with campuses at Lismore and Coffs Harbour in northern New South Wales, Coolangatta and satellite campuses in Brisbane, Sydney, Melbourne and Perth. In 2024, SCU was ranking in the top 100 Universities in the world under 50 years old, in 2026 it was ranking in the top 500 universities globally in the Times Higher Education global University rankings and according to the 2026 QS World University rankings was Awarded the most improved - Oceania As of 2024 SCU has had over 80 000 graduates since its inception in 1994.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('59586688-1e1a-42ce-a93c-c58a8110a4ba'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Logo_of_Swinburne_University_of_Technology.svg/1280px-Logo_of_Swinburne_University_of_Technology.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Logo: Swinburne University of Technology, Public domain, Wikimedia Commons$q$,null,null,$q$The Swinburne University of Technology is a public research university in Melbourne, Australia. It is the modern descendant of the Eastern Suburbs Technical College established in 1908, renamed Swinburne Technical College in 1913 after its co-founders George and Ethel Swinburne. It has three campuses in metropolitan Melbourne: Hawthorn, where its main campus is located; Wantirna; and Croydon, as well the Swinburne University of Technology Sarawak Campus in the East Malaysian state of Sarawak.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('996081c7-44c5-4a01-8b0d-2ce1b5f7b984'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/6/66/Trinity_college_university_of_melbourne.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Biatch at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of Melbourne is a public research university located in Melbourne, Australia. Founded in 1853, it is Australia's second oldest university and the oldest in the state of Victoria. Its main campus is located in Parkville, an inner suburb north of Melbourne's central business district, with several other campuses located across the state of Victoria.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c492cba6-ceb4-40f5-9c96-929ddb74da43'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Main_Walkway%2C_Lower_campus_UNSW.jpg/1280px-Main_Walkway%2C_Lower_campus_UNSW.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: J Bar, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of New South Wales is a public research university based in Sydney, New South Wales, Australia. It was established in 1949. The university consists of seven faculties, through which it offers bachelor's, master's and doctoral degrees.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('598dd4c0-0898-47b9-8969-d510ad327c5e'::uuid,null,null,null,null,$q$The University of Newcastle is a public university in Newcastle, New South Wales, Australia. Established in 1965, it has a primary campus in the Newcastle suburb of Callaghan. The university also operates campuses in Central Coast, Singapore, the Newcastle CBD and Sydney.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3bc9f73e-b9a7-4b82-87ac-4050963fffe1'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/b/b4/UQ-SteeleBldg800.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Gaz at English Wikipedia., CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Queensland is a public research university located primarily in Brisbane, the capital city of the Australian state of Queensland. Established in 1909 by an act of the Queensland Parliament, UQ is one of the six sandstone universities; an informal designation for the oldest university in each state. UQ is also a founding member of edX, the Group of Eight and the international research-intensive Association of Pacific Rim Universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ad5908a3-fb1f-4887-8f6b-9c51aac03b0a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/CurtinUni_Logo.svg/500px-CurtinUni_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/2/24/Curtin_University_from_Edinburgh_Oval.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Kookyrabbit, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Curtin University is an Australian public research university based in Bentley, Perth, Western Australia. It is named after John Curtin, Prime Minister of Australia from 1941 to 1945, and is Western Australia's largest university, with 58,607 students in 2022. WAIT was established in 1966.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('560c1a2e-ed31-48e6-9c73-8d57bca14adf'::uuid,null,null,null,null,$q$Chisholm Institute is a government-owned Technical and Further Education Institute located in south-east Melbourne Australia. It provides adult education in several areas including the arts, hospitality, information technology, trades and business. Chisholm offers over 250 certificate, diploma, advanced diploma, bachelor and graduate certificate courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a7e132f7-a7df-4aa1-965e-62c40a1ad5d6'::uuid,null,null,null,null,$q$Adelaide University is a public research university based in Adelaide, Australia. Founded in 2024 and officially opened on 29 January 2026, it merged the University of Adelaide, the third-oldest university in Australia, and the University of South Australia, which had an antecedent history dating back to 1856. Its two main campuses are located in the Adelaide city centre, one, City West, adjacent to the Adelaide BioMed City and near the Royal Adelaide Hospital, and the other, City East, located at the east end of North Terrace, near the Lot Fourteen tech precincts and containing the original University of Adelaide campus, with additional campuses located across its home state of South Australia.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0efc506c-c3fc-4643-bce1-529d043e3f53'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/2/23/University_of_Sydney_Main_Quadrangle.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: No machine-readable author provided. KittySaturn~commonswiki assumed (based on c, Public domain, Wikimedia Commons$q$,$q$The University of Sydney is a public research university in Sydney, Australia. Founded in 1850, it is the oldest university in both Australia and Oceania. One of Australia's six sandstone universities, it was one of the world's first universities to admit students solely on academic merit, and opened its doors to women on the same basis as men.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bb855057-1765-4c1e-ab67-7160be1773dd'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/AUS_Perth%2C_Central_Business_District%2C_University_of_Western_Australia_0008.jpg/1280px-AUS_Perth%2C_Central_Business_District%2C_University_of_Western_Australia_0008.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: -wuppertaler, CC BY 4.0, Wikimedia Commons$q$,$q$The University of Western Australia is a public research university in Crawley, Western Australia, Australia. UWA was established in 1911 by an act of the Parliament of Western Australia. The university is classed as one of the "sandstone universities", an informal designation given to the oldest university in each state.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('368e2365-f0d1-4c08-bf98-c7d515b2a3bc'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Logo_der_University_of_Canberra.svg/500px-Logo_der_University_of_Canberra.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/8/81/University_of_Canberra_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: 1717 at en.wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of Canberra is a public research university with its main campus located in Bruce, Canberra, Australian Capital Territory. The campus is 2.5 km from Belconnen Town Centre, and 8.7 km from Canberra's Civic Centre. UC offers undergraduate and postgraduate courses through five faculties: Arts and Design; Business, Government and Law; Education; Health; and Science and Technology.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1db228f5-9b29-45ce-a32a-fd74914b0c85'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/USQ_Hervey_Bay_campus2.jpg/1280px-USQ_Hervey_Bay_campus2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Shiftchange, CC0, Wikimedia Commons$q$,$q$The University of Southern Queensland is a public research university based in Toowoomba, Queensland, Australia, with additional campuses in Ipswich and Springfield. Founded in 1967 after a successful campaign by the local Darling Downs community, UniSQ is a medium-sized, regional university and a founding member of the Regional Universities Network. Its main campus occupies a large area of south-western Toowoomba in the suburb of Darling Heights.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ec4030bb-ec4d-4ee7-9ee5-ce382f8a7f2e'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/UniTas-Centenary_Building.jpg/1280px-UniTas-Centenary_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Barrylb at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of Tasmania is a public research university, primarily located in Tasmania, Australia. Founded in 1890, it is Australia's fourth oldest university. Christ College, one of the university's residential colleges, first proposed in 1840 in Lieutenant-Governor Sir John Franklin's Legislative Council, was modelled on the Oxford and Cambridge colleges, and was founded in 1846, making it the oldest tertiary institution in the country.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cfdab7e7-e7bd-45dc-8087-53b55e79b12a'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Ultimo_UTS_Tower.JPG/1280px-Ultimo_UTS_Tower.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: J Bar, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Technology Sydney is a public research university located in Sydney, New South Wales, Australia. The university was founded in its current form in 1988, though its origins as a technical institution can be traced back to the 1870s. UTS is a founding member of the Australian Technology Network, and is a member of Universities Australia and the Worldwide Universities Network.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2006177b-c11a-4291-8452-f40a41828b2b'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/3/3b/UOW_Smart_Infrastructure_Facility.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Nikita Sergey, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Wollongong is an Australian public research university located in the suburb of Keiraville, within the coastal city of Wollongong, New South Wales, approximately 80 kilometres south of Sydney. As of 2023, the university had an enrolment of more than 33,000 students, an alumni base of more than 176,000 and over 2,400 staff members including 16 distinguished professors. In 1951, a division of the New South Wales University of Technology was established in Wollongong for the conduct of diploma courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ed837f5e-9ba1-4c77-88ae-295c44884f29'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Victoria_University_Footscray_Park.jpg/1280px-Victoria_University_Footscray_Park.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Melburnian, CC BY 2.5, Wikimedia Commons$q$,$q$Victoria University is an Australian public research university based in Melbourne, Victoria. It is a dual-sector university, providing courses in both higher education and technical and further education. The university has several campuses in Melbourne Central Business District, Melbourne Western Region, Sydney, Brisbane, as well as Online.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('06087c89-f3e1-4075-9e70-c8f4de4aed35'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Western_Sydney_University_logo.png/500px-Western_Sydney_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Western Sydney University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Uwsparra.JPG/1280px-Uwsparra.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mw12310 at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Western Sydney University, formerly the University of Western Sydney, is an Australian multi-campus public research university in the Greater Western region of Sydney, New South Wales, Australia. The university in its current form was founded in 1989 as a federated network university with an amalgamation between the Nepean College of Advanced Education and the Hawkesbury Agricultural College. The Macarthur Institute of Higher Education was incorporated in the university in 1989.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d1923c21-0041-4c91-9789-fa2ec67e7aa9'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Chippendale_University_of_Notre_Dame.JPG/1280px-Chippendale_University_of_Notre_Dame.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: J Bar, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Notre Dame Australia is a private Catholic university with campuses in Perth, Sydney and Broome. It was established in 1989 by the Parliament of Western Australia with early support from its founding partner and namesake, the University of Notre Dame in the United States. It was originally conceived as a means to train teachers and nurses for the Archdiocese of Perth's Catholic education and healthcare network, but has since expanded into other disciplines.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$)
) v(id,logo_url,logo_credit,image_url,image_credit,description,description_credit)
where s.id = v.id;
commit;

-- Check
select country, count(*) schools, count(nullif(logo_url,'')) with_logo, count(nullif(image_url,'')) with_photo, count(nullif(description,'')) with_text
from public.schools where country in ('Canada','United Kingdom','Australia') group by country order by country;
